declare
  v_invite public.organization_invitations%rowtype;
  v_uid uuid := (select auth.uid());
  v_user_email text;
begin
  if v_uid is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;

  select * into v_invite
  from public.organization_invitations
  where token = p_token
  for update;

  if not found then
    raise exception 'invitation not found' using errcode = 'P0001';
  end if;

  if v_invite.accepted_at is not null then
    raise exception 'invitation already accepted' using errcode = 'P0002';
  end if;

  if v_invite.declined_at is not null then
    raise exception 'invitation revoked' using errcode = 'P0003';
  end if;

  if v_invite.expires_at <= now() then
    raise exception 'invitation expired' using errcode = 'P0004';
  end if;

  select email into v_user_email from auth.users where id = v_uid;

  if v_user_email is null or lower(v_user_email) <> lower(v_invite.email) then
    raise exception 'signed-in email does not match invitation' using errcode = '42501';
  end if;

  -- An inviter may never redeem its own invitation (self-escalation).
  if v_invite.invited_by is null or v_invite.invited_by = v_uid then
    raise exception 'invitation cannot be accepted by its inviter' using errcode = '42501';
  end if;

  -- Role ceiling is re-checked against the inviter at accept time so a
  -- demoted or disabled inviter cannot hand out authority it no longer holds.
  if not public.actor_may_assign_role(
    v_invite.invited_by, v_invite.role_id, v_invite.organization_id
  ) then
    raise exception 'inviter is not allowed to grant this role' using errcode = '42501';
  end if;

  -- The checks above are the authority decision for this write; the
  -- assignment trigger would otherwise evaluate the acceptor, who holds
  -- nothing yet.
  perform set_config('app.rbac_trusted_assignment', 'on', true);

  if v_invite.organization_id is not null then
    -- Accepting never silently upgrades an existing membership; role changes
    -- go through the members flow with its own ceiling.
    if exists (
      select 1
      from public.organization_users
      where organization_users.user_id = v_uid
        and organization_users.organization_id = v_invite.organization_id
    ) then
      raise exception 'you are already a member of this organization' using errcode = 'P0005';
    end if;

    insert into public.organization_users (user_id, organization_id, role_id)
    values (v_uid, v_invite.organization_id, v_invite.role_id);
  else
    insert into public.user_roles (user_id, role_id)
    values (v_uid, v_invite.role_id)
    on conflict do nothing;
  end if;

  update public.organization_invitations
  set accepted_at = now()
  where id = v_invite.id;

  return jsonb_build_object(
    'user_id', v_uid,
    'organization_id', v_invite.organization_id,
    'role_id', v_invite.role_id
  );
end;

