declare
  v_org_id uuid;
  v_quote_id uuid;
  v_status public.quote_status;
  v_valid_until date;
  v_version_id uuid;
  v_version integer;
  v_name text := nullif(trim(p_payload->>'name'), '');
  v_email text := nullif(trim(p_payload->>'email'), '');
  v_optional_ids jsonb := coalesce(p_payload->'selectedOptionalLineIds', '[]'::jsonb);
  v_selected_uuids uuid[];
  v_invalid_count integer;
begin
  if p_org_slug is null or p_quote_id is null then
    raise exception 'quote not found';
  end if;
  if v_name is null or v_email is null then
    raise exception 'name and email are required';
  end if;

  select o.id into v_org_id
  from public.organizations o
  where lower(o.slug) = lower(p_org_slug)
  limit 1;

  if v_org_id is null then
    raise exception 'quote not found';
  end if;

  select q.id, q.status
  into v_quote_id, v_status
  from public.quotes q
  where q.id = p_quote_id
    and q.organization_id = v_org_id
    and q.archived_at is null
  for update;

  if v_quote_id is null then
    raise exception 'quote not found';
  end if;

  if v_status <> 'sent' then
    raise exception 'quote is not in sent state';
  end if;

  select qv.id, qv.version, qv.valid_until
  into v_version_id, v_version, v_valid_until
  from public.quote_versions qv
  where qv.quote_id = v_quote_id
  order by qv.version desc
  limit 1;

  if v_version_id is null then
    raise exception 'quote is not in sent state';
  end if;

  if p_payload ? 'version' and (p_payload->>'version')::integer <> v_version then
    raise exception 'quote updated, reload';
  end if;

  if v_valid_until is not null and v_valid_until < (now() at time zone 'utc')::date then
    raise exception 'quote has expired';
  end if;

  if jsonb_typeof(v_optional_ids) <> 'array' then
    raise exception 'selectedOptionalLineIds must be an array';
  end if;

  if jsonb_array_length(v_optional_ids) > 0 then
    select coalesce(array_agg((value)::uuid), '{}'::uuid[])
    into v_selected_uuids
    from jsonb_array_elements_text(v_optional_ids);

    select count(*) into v_invalid_count
    from unnest(v_selected_uuids) sid
    where not exists (
      select 1
      from public.quote_version_lines l
      where l.quote_version_id = v_version_id
        and l.is_optional = true
        and (l.source_line_id = sid or l.id = sid)
    );

    if v_invalid_count > 0 then
      raise exception 'one or more selected optional lines do not belong to this quote';
    end if;
  end if;

  update public.quotes
  set status = 'accepted',
      accepted_at = now() at time zone 'utc',
      accepted_by_name = v_name,
      accepted_by_email = v_email,
      accepted_ip = p_ip,
      accepted_user_agent = p_user_agent,
      accepted_optional_line_ids = v_optional_ids,
      has_unpublished_changes = false
  where id = v_quote_id;

  update public.quote_versions
  set status = 'accepted'
  where id = v_version_id;

  insert into public.quote_status_history
    (quote_id, organization_id, from_status, to_status,
     actor_customer_name, actor_customer_email, ip, user_agent)
  values
    (v_quote_id, v_org_id, 'sent', 'accepted',
     v_name, v_email, p_ip, p_user_agent);

  perform public.recompute_quote_totals(v_quote_id, v_optional_ids);

  return v_quote_id;
end;

