declare
  v_on date := coalesce(p_on, (now() at time zone 'utc')::date);
  v_start_month smallint;
  v_full_time numeric;
  v_year_start date;
  v_year_end date;
  v_count integer := 0;
  v_row record;
  v_factor numeric;
  v_annual numeric;
  v_month date;
  v_inserted integer;
begin
  select leave_year_start_month, full_time_hours_per_week
  into v_start_month, v_full_time
  from public.hr_settings
  where organization_id = p_organization_id;

  v_start_month := coalesce(v_start_month, 1);
  v_full_time := coalesce(v_full_time, 40);

  v_year_start := make_date(extract(year from v_on)::integer, v_start_month, 1);
  if v_year_start > v_on then
    v_year_start := (v_year_start - interval '1 year')::date;
  end if;
  v_year_end := (v_year_start + interval '1 year' - interval '1 day')::date;

  for v_row in
    select
      employees.id as employee_id,
      employees.start_date,
      employees.end_date,
      policies.id as policy_id,
      policies.time_off_type_id,
      policies.annual_hours,
      policies.accrual_method,
      policies.prorate_by_contract_hours
    from public.employees
    join lateral (
      select time_off_policies.*
      from public.time_off_policies
      where time_off_policies.organization_id = employees.organization_id
        and (
          exists (
            select 1 from public.employee_time_off_policies assignment
            where assignment.employee_id = employees.id
              and assignment.policy_id = time_off_policies.id
              and assignment.starts_on <= v_on
              and (assignment.ends_on is null or assignment.ends_on >= v_on)
          )
          or (
            time_off_policies.is_default
            and not exists (
              select 1
              from public.employee_time_off_policies assignment
              join public.time_off_policies assigned on assigned.id = assignment.policy_id
              where assignment.employee_id = employees.id
                and assigned.time_off_type_id = time_off_policies.time_off_type_id
                and assignment.starts_on <= v_on
                and (assignment.ends_on is null or assignment.ends_on >= v_on)
            )
          )
        )
    ) policies on true
    where employees.organization_id = p_organization_id
      and employees.kind <> 'contractor'
      and employees.status in ('onboarding', 'active', 'offboarding')
      and employees.archived_at is null
  loop
    declare
      v_contract public.employee_contracts := public.employee_contract_on(v_row.employee_id, v_on);
    begin
      if v_contract.leave_entitlement_hours_override is not null then
        v_annual := v_contract.leave_entitlement_hours_override;
      elsif v_row.prorate_by_contract_hours and v_contract.hours_per_week is not null then
        v_annual := v_row.annual_hours * least(v_contract.hours_per_week / v_full_time, 1.5);
      else
        v_annual := v_row.annual_hours;
      end if;
    end;

    if v_row.accrual_method = 'upfront' then
      v_factor := 1;
      if v_row.start_date is not null and v_row.start_date > v_year_start then
        v_factor := greatest(0, (v_year_end - v_row.start_date + 1)::numeric / (v_year_end - v_year_start + 1));
      end if;

      insert into public.time_off_ledger (
        organization_id, employee_id, time_off_type_id, kind, hours, effective_on, note
      )
      select
        p_organization_id, v_row.employee_id, v_row.time_off_type_id, 'grant',
        round(v_annual * v_factor, 2), greatest(v_year_start, coalesce(v_row.start_date, v_year_start)),
        'Annual entitlement ' || to_char(v_year_start, 'YYYY')
      where not exists (
        select 1 from public.time_off_ledger existing
        where existing.employee_id = v_row.employee_id
          and existing.time_off_type_id = v_row.time_off_type_id
          and existing.kind = 'grant'
          and existing.effective_on between v_year_start and v_year_end
      );
      get diagnostics v_inserted = row_count;
      v_count := v_count + v_inserted;
    else
      for v_month in
        select generate_series(
          greatest(v_year_start, date_trunc('month', coalesce(v_row.start_date, v_year_start))::date),
          v_on,
          interval '1 month'
        )::date
      loop
        insert into public.time_off_ledger (
          organization_id, employee_id, time_off_type_id, kind, hours, effective_on, note
        )
        select
          p_organization_id, v_row.employee_id, v_row.time_off_type_id, 'accrual',
          round(v_annual / 12, 2), v_month, 'Monthly accrual ' || to_char(v_month, 'YYYY-MM')
        where not exists (
          select 1 from public.time_off_ledger existing
          where existing.employee_id = v_row.employee_id
            and existing.time_off_type_id = v_row.time_off_type_id
            and existing.kind = 'accrual'
            and existing.effective_on = v_month
        );
        get diagnostics v_inserted = row_count;
        v_count := v_count + v_inserted;
      end loop;
    end if;
  end loop;

  return v_count;
end;

