declare
  v_role public.roles%rowtype;
  v_keys text[];
  v_held text[];
begin
  if p_actor_user_id is null or p_role_id is null then
    return false;
  end if;

  select * into v_role from public.roles where id = p_role_id;
  if not found then
    return false;
  end if;

  if v_role.scope = 'system' then
    if p_organization_id is not null then
      return false;
    end if;

    if public.resolve_actor_scope_permissions(
      p_actor_user_id, 'system', null, array['system.roles.manage']
    ) @> array['system.roles.manage'] then
      return true;
    end if;

    select coalesce(array_agg(distinct permissions.key), '{}'::text[])
    into v_keys
    from public.role_permissions
    join public.permissions on permissions.id = role_permissions.permission_id
    where role_permissions.role_id = v_role.id
      and permissions.scope = 'system';

    v_held := public.resolve_actor_scope_permissions(p_actor_user_id, 'system', null, v_keys);
    return cardinality(v_held) = cardinality(v_keys);
  end if;

  if p_organization_id is null then
    return false;
  end if;

  -- Custom roles belong to exactly one organization.
  if v_role.organization_id is not null and v_role.organization_id <> p_organization_id then
    return false;
  end if;

  if public.resolve_actor_scope_permissions(
    p_actor_user_id, 'system', null, array['system.users.manage']
  ) @> array['system.users.manage'] then
    return true;
  end if;

  -- Effective grant set of the role inside this organization: role defaults
  -- plus explicit per-organization allows. Denies are ignored on purpose so
  -- the ceiling only ever requires more from the grantor, never less.
  select coalesce(array_agg(distinct effective.key), '{}'::text[])
  into v_keys
  from (
    select permissions.key
    from public.role_permissions
    join public.permissions on permissions.id = role_permissions.permission_id
    where role_permissions.role_id = v_role.id
      and permissions.scope = 'organization'
    union
    select permissions.key
    from public.organization_permission_overrides as overrides
    join public.permissions on permissions.id = overrides.permission_id
    where overrides.role_id = v_role.id
      and overrides.organization_id = p_organization_id
      and overrides.granted
      and permissions.scope = 'organization'
  ) as effective;

  v_held := public.resolve_actor_scope_permissions(
    p_actor_user_id, 'organization', p_organization_id, v_keys
  );
  return cardinality(v_held) = cardinality(v_keys);
end;

