  if not public.has_org_permission(p_organization_id, 'organization.orders.update') then
    raise insufficient_privilege using message = 'order update permission required';
  end if;

  if not exists (
    select 1 from public.orders
    where orders.id = p_order_id
      and orders.organization_id = p_organization_id
      and orders.status in ('confirmed', 'on_hold')
  ) then
    raise exception 'only confirmed orders hold stock'
      using errcode = '22023', hint = 'order_not_confirmed';
  end if;

  return public.allocate_order_lines(p_organization_id, p_order_id);
end;

