declare
  v_line record;
  v_target numeric(12, 3);
  v_held numeric(12, 3);
  v_shortfall numeric(12, 3);
  v_backordered integer := 0;
  v_short integer := 0;
begin
  for v_line in
    select order_lines.id, order_lines.product_id, order_lines.quantity,
      order_lines.quantity_cancelled, progress.fulfilled
    from public.order_lines
    join public.products on products.id = order_lines.product_id
    join public.order_line_progress(p_organization_id, p_order_id) as progress
      on progress.order_line_id = order_lines.id
    where order_lines.order_id = p_order_id
      and order_lines.line_type = 'product'
      and products.track_inventory
      and products.product_type = 'physical'
    order by order_lines.position, order_lines.id
  loop
    v_target := greatest(v_line.quantity - v_line.quantity_cancelled - v_line.fulfilled, 0);

    select coalesce(sum(inventory_allocations.quantity), 0)
    into v_held
    from public.inventory_allocations
    where inventory_allocations.order_line_id = v_line.id
      and inventory_allocations.state = 'reserved';

    if v_held > v_target then
      perform public.release_order_line_allocations(
        p_organization_id, v_line.id, v_held - v_target, 'order changed'
      );
      v_held := v_target;
    elsif v_held < v_target then
      v_held := v_held + public.allocate_product_stock(
        p_organization_id, v_line.product_id, v_target - v_held, null, null, null,
        'order confirmed', null, null, auth.uid(), null, v_line.id
      );
    end if;

    v_shortfall := greatest(v_target - v_held, 0);
    if public.sync_order_line_backorder(p_organization_id, v_line.id, v_shortfall) then
      v_backordered := v_backordered + 1;
    elsif v_shortfall > 0 then
      v_short := v_short + 1;
    end if;
  end loop;

  return jsonb_build_object('backorderedLines', v_backordered, 'shortLines', v_short);
end;

