declare
  -- Sanitize the base up front so every candidate matches the username format
  -- and the loop can only ever be waiting on a free suffix.
  v_base text := public.normalize_username_component(p_base);
  v_candidate text;
  v_suffix text := '';
  v_counter integer := 2;
begin
  if v_base = '' then
    v_base := 'user';
  end if;
  if v_base !~ '^[a-z]' then
    v_base := 'u_' || v_base;
  end if;
  if char_length(v_base) < 3 then
    v_base := left(v_base || '_usr', 30);
  end if;
  v_base := left(v_base, 30);

  loop
    v_candidate := left(v_base, 30 - char_length(v_suffix)) || v_suffix;

    if v_candidate ~ '^[a-z][a-z0-9_]{2,29}$'
       and not exists (
         select 1
         from public.profiles p
         where p.username = v_candidate
           and p.user_id <> p_user_id
       ) then
      return v_candidate;
    end if;

    v_suffix := '_' || v_counter::text;
    v_counter := v_counter + 1;

    if v_counter > 100000 then
      -- Fall back to a random tail rather than spinning forever on a crowded base.
      return left(v_base, 21) || '_' || substr(md5(p_user_id::text || clock_timestamp()::text), 1, 8);
    end if;
  end loop;
end;

