select coalesce(
  (select task_materials.variant_id from public.task_materials where task_materials.id = p_task_material_id),
  (select quote_version_lines.variant_id from public.quote_version_lines where quote_version_lines.id = p_quote_version_line_id),
  (select invoice_lines.variant_id from public.invoice_lines where invoice_lines.id = p_invoice_line_id),
  (select order_lines.variant_id from public.order_lines where order_lines.id = p_order_line_id),
  public.product_default_variant_id(p_product_id)
);

declare
  v_user_id uuid := auth.uid();
  v_material record;
  v_allocation_count integer;
  v_invoiced boolean;
begin
  if v_user_id is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;

  if not public.has_org_permission(
    p_organization_id,
    'organization.tasks.update'
  ) then
    raise insufficient_privilege using message = 'task update permission required';
  end if;

  if p_consume is null then
    raise exception 'p_consume is required' using errcode = '22004';
  end if;

  perform 1
  from public.tasks
  where tasks.id = p_task_id
    and tasks.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'task not found in organization' using errcode = '23503';
  end if;

  perform 1
  from public.task_materials
  where task_materials.organization_id = p_organization_id
    and task_materials.task_id = p_task_id
  order by task_materials.product_id, task_materials.id
  for update;

  for v_material in
    select task_materials.*
    from public.task_materials
    where task_materials.organization_id = p_organization_id
      and task_materials.task_id = p_task_id
    order by task_materials.product_id, task_materials.id
  loop
    select count(*)
    into v_allocation_count
    from public.inventory_allocations
    where inventory_allocations.organization_id = p_organization_id
      and inventory_allocations.task_material_id = v_material.id;

    if p_consume then
      if v_material.stock_state = 'consumed' then
        continue;
      end if;

      if v_material.stock_state = 'untracked' or v_allocation_count = 0 then
        if v_material.stock_state = 'untracked' and v_allocation_count <> 0 then
          raise exception 'untracked task material cannot have stock allocations'
            using errcode = '23514';
        end if;

        update public.task_materials
        set
          stock_state = 'consumed',
          consumed_at = now(),
          updated_by = v_user_id
        where task_materials.id = v_material.id;

        continue;
      end if;

      perform public.consume_allocations(
        p_organization_id,
        v_material.id,
        null,
        null,
        'task material consumed',
        v_material.quote_id,
        null,
        v_user_id
      );

      update public.task_materials
      set
        stock_state = 'consumed',
        consumed_at = now(),
        updated_by = v_user_id
      where task_materials.id = v_material.id;
    else
      if v_material.stock_state <> 'consumed' then
        continue;
      end if;

      select exists (
        select 1
        from public.invoice_tasks
        join public.invoices
          on invoices.id = invoice_tasks.invoice_id
          and invoices.organization_id = invoice_tasks.organization_id
        join public.invoice_lines
          on invoice_lines.invoice_id = invoices.id
          and invoice_lines.organization_id = invoices.organization_id
        where invoice_tasks.organization_id = p_organization_id
          and invoice_tasks.task_id = p_task_id
          and invoices.status in ('sent', 'paid', 'overdue')
          and invoices.archived_at is null
          and invoice_lines.kind = 'line'
          and invoice_lines.stock_mode = 'task'
          and invoice_lines.product_id = v_material.product_id
      ) into v_invoiced;

      if v_invoiced then
        continue;
      end if;

      if v_allocation_count = 0 then
        update public.task_materials
        set
          stock_state = case
            when exists (
              select 1
              from public.inventory_stock_records
              where inventory_stock_records.organization_id = p_organization_id
                and inventory_stock_records.product_id = v_material.product_id
            ) then 'reserved'::public.task_material_stock_state
            else 'untracked'::public.task_material_stock_state
          end,
          consumed_at = null,
          updated_by = v_user_id
        where task_materials.id = v_material.id;

        continue;
      end if;

      perform public.restore_allocations(
        p_organization_id,
        v_material.id,
        null,
        null,
        'task material restored after task reopening',
        v_material.quote_id,
        null,
        v_user_id
      );

      update public.task_materials
      set
        stock_state = 'reserved',
        consumed_at = null,
        updated_by = v_user_id
      where task_materials.id = v_material.id;
    end if;
  end loop;
end;

