declare
  v_uid uuid := (select auth.uid());
  v_permission_id uuid;
begin
  if v_uid is null or p_permission is null then
    return false;
  end if;

  select permissions.id
  into v_permission_id
  from public.permissions
  where permissions.key = p_permission
    and permissions.scope = p_scope;

  if v_permission_id is null then
    return false;
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.user_id = v_uid
      and profiles.disabled_at is null
  ) then
    return false;
  end if;

  if p_scope = 'system' then
    return exists (
      select 1
      from public.user_roles
      join public.roles
        on roles.id = user_roles.role_id
        and roles.scope = 'system'
      join public.role_permissions
        on role_permissions.role_id = roles.id
        and role_permissions.permission_id = v_permission_id
      where user_roles.user_id = v_uid
    );
  end if;

  if p_scope <> 'organization' or p_scope_id is null then
    return false;
  end if;

  if not exists (
    select 1
    from public.organizations
    where organizations.id = p_scope_id
      and organizations.disabled_at is null
  ) then
    return false;
  end if;

  if exists (
    select 1
    from public.user_roles
    join public.roles
      on roles.id = user_roles.role_id
      and roles.scope = 'system'
      and roles.key = 'system-admin'
    where user_roles.user_id = v_uid
  ) then
    return true;
  end if;

  return (
    with membership as (
      select organization_users.role_id
      from public.organization_users
      join public.roles
        on roles.id = organization_users.role_id
        and roles.scope = 'organization'
        and (
          roles.organization_id is null
          or roles.organization_id = organization_users.organization_id
        )
      where organization_users.user_id = v_uid
        and organization_users.organization_id = p_scope_id
    ),
    explicit as (
      select overrides.granted
      from public.organization_permission_overrides as overrides
      join membership on membership.role_id = overrides.role_id
      where overrides.organization_id = p_scope_id
        and overrides.permission_id = v_permission_id
    )
    select
      case
        when exists (select 1 from explicit where explicit.granted = false) then false
        when exists (select 1 from explicit where explicit.granted = true) then true
        else exists (
          select 1
          from public.role_permissions
          join membership on membership.role_id = role_permissions.role_id
          where role_permissions.permission_id = v_permission_id
        )
      end
  );
end;

