declare
  v_uid uuid := (select auth.uid());
  v_next_user uuid;
begin
  if v_uid is null or p_request.status <> 'requested' then
    return false;
  end if;
  if p_request.expires_at is not null and p_request.expires_at <= now() then
    return false;
  end if;
  if exists (
    select 1 from public.approval_decisions decision
    where decision.request_id = p_request.id and decision.decided_by = v_uid
  ) then
    return false;
  end if;

  if public.is_approval_requester(p_request) then
    -- Confirm means the human behind the actor confirms it themselves.
    return p_request.requirement = 'confirm' or p_request.allow_self;
  end if;

  if not public.is_approval_approver(p_request) then
    return false;
  end if;

  if p_request.approver_mode = 'sequential' and cardinality(p_request.approver_user_ids) > 0 then
    select candidate
    into v_next_user
    from unnest(p_request.approver_user_ids) with ordinality as approvers(candidate, position)
    where not exists (
      select 1 from public.approval_decisions decision
      where decision.request_id = p_request.id and decision.decided_by = approvers.candidate
    )
    order by approvers.position
    limit 1;
    if v_next_user is not null and v_next_user <> v_uid
      and v_uid = any(p_request.approver_user_ids) then
      return false;
    end if;
  end if;

  return true;
end;

