declare
  v_status public.order_status;
  v_line record;
  v_shipped numeric := 0;
  v_result public.order_status;
begin
  if not public.has_org_permission(p_organization_id, 'organization.orders.cancel') then
    raise insufficient_privilege using message = 'order cancel permission required';
  end if;

  select orders.status into v_status
  from public.orders
  where orders.id = p_order_id
    and orders.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'order not found' using errcode = 'P0002';
  end if;

  if v_status not in ('draft', 'confirmed', 'on_hold') then
    raise exception 'this order can no longer be cancelled'
      using errcode = '22023', hint = 'order_not_cancellable';
  end if;

  for v_line in
    select order_lines.id, order_lines.quantity, progress.fulfilled
    from public.order_lines
    join public.order_line_progress(p_organization_id, p_order_id) as progress
      on progress.order_line_id = order_lines.id
    where order_lines.order_id = p_order_id
  loop
    perform public.release_order_line_allocations(
      p_organization_id, v_line.id, null, 'order cancelled'
    );
    perform public.sync_order_line_backorder(p_organization_id, v_line.id, 0);
    update public.order_lines
    set quantity_cancelled = greatest(v_line.quantity - v_line.fulfilled, 0)
    where order_lines.id = v_line.id;
    v_shipped := v_shipped + v_line.fulfilled;
  end loop;

  v_result := case when v_shipped > 0 then 'completed' else 'cancelled' end;

  perform set_config('app.shipment_transition', 'on', true);
  update public.shipments
  set status = 'cancelled'
  where shipments.order_id = p_order_id
    and shipments.direction = 'outbound'
    and shipments.shipped_at is null
    and shipments.status <> 'cancelled';
  perform set_config('app.shipment_transition', 'off', true);

  update public.orders
  set status = v_result,
    cancelled_at = case when v_result = 'cancelled' then now() else cancelled_at end,
    completed_at = case when v_result = 'completed' then now() else completed_at end,
    cancel_reason = nullif(btrim(p_reason), ''),
    updated_by = auth.uid()
  where orders.id = p_order_id;

  return v_result;
end;

