declare
  v_shipment record;
begin
  select shipments.id, shipments.direction, shipments.status, shipments.shipped_at,
    shipments.delivered_at
  into v_shipment
  from public.shipments
  where shipments.id = p_shipment_id
    and shipments.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'shipment not found' using errcode = 'P0002';
  end if;

  if not public.has_org_permission(
    p_organization_id,
    case when v_shipment.direction = 'inbound'
      then 'organization.purchase-orders.receive'
      else 'organization.orders.fulfill'
    end
  ) then
    raise insufficient_privilege using message = 'shipment permission required';
  end if;

  if v_shipment.shipped_at is not null or v_shipment.delivered_at is not null then
    raise exception 'shipped shipments cannot be cancelled; create a return instead'
      using errcode = '22023', hint = 'shipment_already_shipped';
  end if;

  perform set_config('app.shipment_transition', 'on', true);
  update public.shipments set status = 'cancelled' where shipments.id = p_shipment_id;
  perform set_config('app.shipment_transition', 'off', true);
end;

