declare
  v_mismatches integer;
begin
  if auth.uid() is not null
    and p_organization_id is not null
    and not public.has_org_permission(p_organization_id, 'organization.assets.view')
  then
    raise insufficient_privilege using message = 'asset view permission required';
  end if;

  select count(*)
  into v_mismatches
  from public.inventory_stock_records
  where (p_organization_id is null or inventory_stock_records.organization_id = p_organization_id)
    and inventory_stock_records.allocated_quantity <> coalesce((
      select sum(inventory_allocations.quantity)
      from public.inventory_allocations
      where inventory_allocations.stock_record_id = inventory_stock_records.id
        and inventory_allocations.state = 'reserved'
    ), 0);

  if v_mismatches > 0 then
    raise exception 'inventory allocation integrity failed for % stock records', v_mismatches
      using errcode = '23514';
  end if;
end;

declare
  v_checkpoint public.ai_agent_tool_checkpoints%rowtype;
begin
  if current_user <> 'service_role' then
    raise exception 'claim_ai_agent_tool_checkpoint requires service_role'
      using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_run_id::text, 0)
  );

  select checkpoint.*
  into v_checkpoint
  from public.ai_agent_tool_checkpoints as checkpoint
  where checkpoint.run_id = p_run_id
    and checkpoint.call_key = p_call_key;

  if found then
    if v_checkpoint.tool_name is distinct from p_tool_name
      or v_checkpoint.input_hash is distinct from p_input_hash
    then
      return jsonb_build_object('kind', 'conflict');
    end if;
    if v_checkpoint.status = 'completed' then
      return jsonb_build_object('kind', 'completed', 'output', v_checkpoint.output);
    end if;
    return jsonb_build_object('kind', 'blocked');
  end if;

  if exists (
    select 1
    from public.ai_agent_tool_checkpoints as checkpoint
    where checkpoint.run_id = p_run_id
      and checkpoint.status = 'claimed'
  ) then
    return jsonb_build_object('kind', 'busy');
  end if;

  insert into public.ai_agent_tool_checkpoints (
    run_id,
    call_key,
    tool_name,
    input_hash
  )
  values (
    p_run_id,
    p_call_key,
    p_tool_name,
    p_input_hash
  )
  returning * into v_checkpoint;

  return jsonb_build_object(
    'checkpointId',
    v_checkpoint.id,
    'kind',
    'claimed'
  );
end;

