declare
  v_status public.order_status;
  v_allocation jsonb;
begin
  if not public.has_org_permission(p_organization_id, 'organization.orders.confirm') then
    raise insufficient_privilege using message = 'order confirm permission required';
  end if;

  select orders.status into v_status
  from public.orders
  where orders.id = p_order_id
    and orders.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'order not found' using errcode = 'P0002';
  end if;

  if v_status <> 'draft' then
    raise exception 'only draft orders can be confirmed'
      using errcode = '22023', hint = 'order_not_draft';
  end if;

  if not exists (select 1 from public.order_lines where order_lines.order_id = p_order_id) then
    raise exception 'an order needs at least one line'
      using errcode = '22023', hint = 'order_empty';
  end if;

  update public.orders
  set status = 'confirmed', confirmed_at = now(), updated_by = auth.uid()
  where orders.id = p_order_id;

  v_allocation := public.allocate_order_lines(p_organization_id, p_order_id);
  return v_allocation || jsonb_build_object('status', 'confirmed');
end;

