declare
  v_request public.approval_requests%rowtype;
begin
  select * into v_request
  from public.approval_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'approval_not_found' using errcode = 'P0002';
  end if;

  if v_request.status <> 'approved' then
    raise exception 'approval_not_approved' using errcode = 'P0001';
  end if;

  if v_request.input_fingerprint is not null
    and v_request.input_fingerprint is distinct from p_input_fingerprint then
    update public.approval_requests
    set status = 'superseded'
    where id = v_request.id;
    raise exception 'approval_superseded' using errcode = 'P0001';
  end if;

  if (select auth.uid()) is not null
    and not public.is_approval_requester(v_request)
    and not public.is_approval_approver(v_request) then
    raise exception 'approval_forbidden' using errcode = '42501';
  end if;

  update public.approval_requests
  set status = 'consumed',
      consumed_at = now()
  where id = v_request.id
  returning * into v_request;

  return v_request;
end;

