declare
  v_user_id uuid := (select auth.uid());
  v_existing public.file_copy_operations;
  v_operation public.file_copy_operations;
  v_source record;
  v_target_parent_id uuid;
  v_target_node public.file_nodes;
  v_target_name text;
  v_suffix integer;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if cardinality(p_source_node_ids) not between 1 and 200
    or p_conflict_strategy not in ('fail', 'rename')
    or length(trim(p_idempotency_key)) = 0 then
    raise exception 'Invalid copy operation' using errcode = '23514';
  end if;

  select * into v_existing
  from public.file_copy_operations
  where organization_id = p_organization_id
    and created_by = v_user_id
    and idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.source_node_ids <> p_source_node_ids
      or v_existing.destination_drive_id <> p_destination_drive_id
      or v_existing.destination_parent_id is distinct from p_destination_parent_id
      or v_existing.conflict_strategy <> p_conflict_strategy then
      raise exception 'Idempotency key was used for a different copy operation'
        using errcode = '23505';
    end if;
    return v_existing;
  end if;

  if not public.has_org_permission(p_organization_id, 'organization.files.create')
    or not public.has_file_drive_access(p_destination_drive_id, 'editor')
    or not exists (
      select 1
      from public.file_drives
      where id = p_destination_drive_id
        and organization_id = p_organization_id
        and lifecycle_state = 'active'
    )
    or (
      p_destination_parent_id is not null
      and not exists (
        select 1
        from public.file_nodes
        where id = p_destination_parent_id
          and drive_id = p_destination_drive_id
          and organization_id = p_organization_id
          and kind = 'folder'
          and deleted_at is null
          and public.has_file_node_access(id, 'editor')
      )
    )
    or (
      p_destination_parent_id is null
      and exists (
        select 1
        from public.file_drives
        where id = p_destination_drive_id
          and drive_type = 'customers'
      )
    ) then
    raise exception 'Copy destination is not allowed' using errcode = '42501';
  end if;

  if (
    select count(*)
    from public.file_nodes
    where id = any (p_source_node_ids)
      and organization_id = p_organization_id
      and deleted_at is null
      and public.has_file_node_access(id, 'viewer')
  ) <> cardinality(p_source_node_ids) then
    raise exception 'One or more source nodes are not accessible' using errcode = '42501';
  end if;
  if exists (
    with recursive selected_tree as (
      select id, organization_id
      from public.file_nodes
      where id = any (p_source_node_ids)
      union
      select child.id, child.organization_id
      from public.file_nodes as child
      inner join selected_tree as parent on child.parent_id = parent.id
      where child.deleted_at is null
    )
    select 1
    from selected_tree
    where organization_id <> p_organization_id
      or not public.has_file_node_access(id, 'viewer')
  ) then
    raise exception 'A source descendant is not accessible' using errcode = '42501';
  end if;

  if p_destination_parent_id is not null and exists (
    with recursive selected_tree as (
      select id
      from public.file_nodes
      where id = any (p_source_node_ids)
      union
      select child.id
      from public.file_nodes as child
      inner join selected_tree as parent on child.parent_id = parent.id
      where child.deleted_at is null
    )
    select 1 from selected_tree where id = p_destination_parent_id
  ) then
    raise exception 'A folder cannot be copied into its own subtree' using errcode = '23514';
  end if;

  insert into public.file_copy_operations (
    id, organization_id, created_by, idempotency_key, source_node_ids,
    destination_drive_id, destination_parent_id, conflict_strategy
  ) values (
    p_operation_id, p_organization_id, v_user_id, p_idempotency_key,
    p_source_node_ids, p_destination_drive_id, p_destination_parent_id,
    p_conflict_strategy
  )
  returning * into v_operation;

  for v_source in
    with recursive
    requested_roots as (
      select node.*, requested.ordinality
      from unnest(p_source_node_ids) with ordinality as requested(id, ordinality)
      inner join public.file_nodes as node on node.id = requested.id
      where not exists (
        with recursive ancestors as (
          select parent_id
          from public.file_nodes
          where id = node.id
          union all
          select parent.parent_id
          from public.file_nodes as parent
          inner join ancestors on parent.id = ancestors.parent_id
          where ancestors.parent_id is not null
        )
        select 1
        from ancestors
        where parent_id = any (p_source_node_ids)
      )
    ),
    selected_tree as (
      select root.*, 0 as depth, root.id as root_id
      from requested_roots as root
      union all
      select child.*, parent.ordinality, parent.depth + 1, parent.root_id
      from public.file_nodes as child
      inner join selected_tree as parent on child.parent_id = parent.id
      where child.deleted_at is null
    )
    select *
    from selected_tree
    order by ordinality, depth, created_at, id
  loop
    if v_source.depth = 0 then
      v_target_parent_id := p_destination_parent_id;
      v_target_name := v_source.name;
      if exists (
        select 1
        from public.file_nodes
        where drive_id = p_destination_drive_id
          and parent_id is not distinct from p_destination_parent_id
          and lower(name) = lower(v_target_name)
          and deleted_at is null
      ) then
        if p_conflict_strategy = 'fail' then
          raise exception 'A node with this name already exists' using errcode = '23505';
        end if;
        v_suffix := 1;
        loop
          v_target_name := v_source.name || ' (copy'
            || case when v_suffix = 1 then '' else ' ' || v_suffix::text end || ')';
          exit when not exists (
            select 1
            from public.file_nodes
            where drive_id = p_destination_drive_id
              and parent_id is not distinct from p_destination_parent_id
              and lower(name) = lower(v_target_name)
              and deleted_at is null
          );
          v_suffix := v_suffix + 1;
        end loop;
      end if;
    else
      select target_node_id into v_target_parent_id
      from public.file_copy_operation_items
      where operation_id = p_operation_id and source_node_id = v_source.parent_id;
      v_target_name := v_source.name;
    end if;

    insert into public.file_nodes (
      organization_id, drive_id, parent_id, kind, name, source,
      external_metadata, created_by
    ) values (
      p_organization_id, p_destination_drive_id, v_target_parent_id,
      v_source.kind, v_target_name, 'internal',
      v_source.external_metadata || jsonb_build_object('copiedFromNodeId', v_source.id),
      v_user_id
    )
    returning * into v_target_node;

    insert into public.file_copy_operation_items (
      operation_id, organization_id, source_node_id, target_node_id,
      source_version_id, status
    ) values (
      p_operation_id, p_organization_id, v_source.id, v_target_node.id,
      v_source.current_version_id,
      case when v_source.current_version_id is null then 'completed' else 'pending' end
    );
  end loop;

  update public.file_copy_operations
  set
    total_items = (
      select count(*) from public.file_copy_operation_items where operation_id = p_operation_id
    ),
    completed_items = (
      select count(*) from public.file_copy_operation_items
      where operation_id = p_operation_id and status = 'completed'
    ),
    status = case
      when not exists (
        select 1 from public.file_copy_operation_items
        where operation_id = p_operation_id and status <> 'completed'
      ) then 'completed'
      else 'metadata-ready'
    end,
    completed_at = case
      when not exists (
        select 1 from public.file_copy_operation_items
        where operation_id = p_operation_id and status <> 'completed'
      ) then (now() at time zone 'utc')
      else null
    end
  where id = p_operation_id
  returning * into v_operation;
  return v_operation;
end;

