declare
  v_node public.file_nodes;
  v_version public.file_versions;
  v_number integer;
begin
  select * into v_node from public.file_nodes where id = p_node_id for update;
  if v_node.id is null or v_node.kind <> 'file' or v_node.deleted_at is not null then
    raise exception 'Active file node not found' using errcode = 'P0002';
  end if;
  if not public.has_file_node_access(v_node.id, 'editor') then
    raise exception 'File version creation is not allowed' using errcode = '42501';
  end if;
  select coalesce(max(version_number), 0) + 1 into v_number
  from public.file_versions
  where node_id = v_node.id;

  insert into public.file_versions (
    organization_id, drive_id, node_id, version_number, media_type, byte_size,
    storage_bucket, storage_path, checksum, etag, source_modified_at, created_by,
    retention_until
  ) values (
    v_node.organization_id, v_node.drive_id, v_node.id, v_number, p_media_type,
    p_byte_size, p_storage_bucket, p_storage_path, p_checksum, p_etag,
    p_source_modified_at, (select auth.uid()),
    (now() at time zone 'utc')
      + make_interval(days => public.get_file_retention_days(v_node.organization_id))
  )
  returning * into v_version;

  update public.file_nodes set current_version_id = v_version.id where id = v_node.id;
  return v_version;
