declare
  v_user_id uuid := (select auth.uid());
  v_existing public.file_zip_exports;
  v_export public.file_zip_exports;
  v_total_bytes bigint;
  v_total_items integer;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if cardinality(p_source_node_ids) not between 1 and 200
    or length(trim(p_file_name)) = 0
    or length(trim(p_idempotency_key)) = 0 then
    raise exception 'Invalid ZIP export' using errcode = '23514';
  end if;
  select * into v_existing
  from public.file_zip_exports
  where organization_id = p_organization_id
    and created_by = v_user_id
    and idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.source_node_ids <> p_source_node_ids or v_existing.file_name <> p_file_name then
      raise exception 'Idempotency key was used for a different ZIP export'
        using errcode = '23505';
    end if;
    return v_existing;
  end if;
  if not public.has_org_permission(p_organization_id, 'organization.files.view')
    or (
      select count(*)
      from public.file_nodes
      where id = any (p_source_node_ids)
        and organization_id = p_organization_id
        and deleted_at is null
        and public.has_file_node_access(id, 'viewer')
    ) <> cardinality(p_source_node_ids) then
    raise exception 'One or more ZIP sources are not accessible' using errcode = '42501';
  end if;

  insert into public.file_zip_exports (
    id, organization_id, created_by, idempotency_key, delivery_mode,
    source_node_ids, file_name
  ) values (
    p_export_id, p_organization_id, v_user_id, p_idempotency_key, 'async',
    p_source_node_ids, p_file_name
  )
  returning * into v_export;

  insert into public.file_zip_export_items (
    export_id, organization_id, node_id, version_id, archive_path,
    media_type, byte_size, storage_bucket, storage_path
  )
  with recursive
  requested_roots as (
    select node.*, requested.ordinality
    from unnest(p_source_node_ids) with ordinality as requested(id, ordinality)
    inner join public.file_nodes as node on node.id = requested.id
    where not exists (
      with recursive ancestors as (
        select parent_id from public.file_nodes where id = node.id
        union all
        select parent.parent_id
        from public.file_nodes as parent
        inner join ancestors on parent.id = ancestors.parent_id
        where ancestors.parent_id is not null
      )
      select 1 from ancestors where parent_id = any (p_source_node_ids)
    )
  ),
  selected_tree as (
    select root.*, root.name::text as archive_path
    from requested_roots as root
    union all
    select child.*, parent.ordinality, (parent.archive_path || '/' || child.name)::text
    from public.file_nodes as child
    inner join selected_tree as parent on child.parent_id = parent.id
    where child.deleted_at is null
  )
  select
    p_export_id, p_organization_id, node.id, version.id, node.archive_path,
    version.media_type, coalesce(version.byte_size, 0), version.storage_bucket,
    version.storage_path
  from selected_tree as node
  left join public.file_versions as version on version.id = node.current_version_id
  where public.has_file_node_access(node.id, 'viewer');

  if (
    select count(*)
    from public.file_zip_export_items
    where export_id = p_export_id
  ) <> (
    with recursive selected_tree as (
      select id from public.file_nodes where id = any (p_source_node_ids)
      union
      select child.id
      from public.file_nodes as child
      inner join selected_tree as parent on child.parent_id = parent.id
      where child.deleted_at is null
    )
    select count(*) from selected_tree
  ) then
    raise exception 'A ZIP descendant is not accessible' using errcode = '42501';
  end if;

  select count(*), coalesce(sum(byte_size), 0)
  into v_total_items, v_total_bytes
  from public.file_zip_export_items
  where export_id = p_export_id;
  update public.file_zip_exports
  set
    total_items = v_total_items,
    total_bytes = v_total_bytes,
    delivery_mode = case
      when v_total_bytes <= p_direct_max_bytes and v_total_items <= p_direct_max_items
        then 'direct'
      else 'async'
    end,
    status = case
      when v_total_bytes <= p_direct_max_bytes and v_total_items <= p_direct_max_items
        then 'ready'
      else 'queued'
    end
  where id = p_export_id
  returning * into v_export;
  return v_export;
end;

