declare
  v_header public.invoices%rowtype;
  v_invoice_id uuid;
  v_linked_rows integer;
begin
  if jsonb_typeof(p_header) <> 'object' then
    raise exception 'invoice header must be an object' using errcode = '22023';
  end if;
  v_header := jsonb_populate_record(null::public.invoices, p_header);
  if v_header.organization_id is distinct from p_organization_id then
    raise exception 'invoice organization mismatch' using errcode = '23514';
  end if;
  if not exists (
    select 1 from public.customers
    where id = v_header.customer_id and organization_id = p_organization_id
  ) then
    raise exception 'invoice customer not found in organization' using errcode = '23503';
  end if;
  if v_header.invoice_template_id is not null and not exists (
    select 1 from public.templates
    where id = v_header.invoice_template_id
      and organization_id = p_organization_id
      and type = 'invoice'
  ) then
    raise exception 'invoice template not found in organization' using errcode = '23503';
  end if;
  if v_header.source_quote_id is not null and not exists (
    select 1 from public.quotes
    where id = v_header.source_quote_id and organization_id = p_organization_id
  ) then
    raise exception 'source quote not found in organization' using errcode = '23503';
  end if;
  if v_header.customer_contact_id is not null and not exists (
    select 1 from public.customer_contacts
    where id = v_header.customer_contact_id
      and customer_id = v_header.customer_id
      and organization_id = p_organization_id
  ) then
    raise exception 'invoice customer contact not found for customer' using errcode = '23503';
  end if;
  if v_header.order_id is not null and not exists (
    select 1 from public.orders
    where id = v_header.order_id
      and customer_id = v_header.customer_id
      and organization_id = p_organization_id
  ) then
    raise exception 'invoice order not found for customer' using errcode = '23503';
  end if;

  insert into public.invoices (
    organization_id, customer_id, due_days, invoice_template_id, status,
    title, intro, terms, currency, vat_inclusive,
    discount_kind, discount_value, discount_description, issue_date, due_date,
    public_message, footer_text, source_quote_id, created_by, updated_by,
    delivery_date, kind, original_invoice_id, vat_regime,
    terms_rich_text, terms_url, terms_pdf_file_id, terms_pdf_version_id,
    customer_contact_id, customer_reference, online_payment_enabled,
    order_id, promotion_id
  ) values (
    p_organization_id, v_header.customer_id, v_header.due_days,
    v_header.invoice_template_id, coalesce(v_header.status, 'draft'),
    v_header.title, v_header.intro, v_header.terms,
    v_header.currency, v_header.vat_inclusive, v_header.discount_kind,
    v_header.discount_value, v_header.discount_description, v_header.issue_date,
    v_header.due_date,
    v_header.public_message, v_header.footer_text, v_header.source_quote_id,
    v_header.created_by, v_header.updated_by,
    v_header.delivery_date, coalesce(v_header.kind, 'invoice'),
    v_header.original_invoice_id, coalesce(v_header.vat_regime, 'standard'),
    v_header.terms_rich_text, v_header.terms_url, v_header.terms_pdf_file_id,
    v_header.terms_pdf_version_id,
    v_header.customer_contact_id, v_header.customer_reference,
    coalesce(v_header.online_payment_enabled, true),
    v_header.order_id, v_header.promotion_id
  )
  returning id into v_invoice_id;

  perform public.replace_invoice_aggregate_children(
    p_organization_id, v_invoice_id, p_lines, p_task_ids, true, true
  );
  perform public.recompute_invoice_totals(v_invoice_id);

  if v_header.source_quote_id is not null then
    update public.quotes
    set invoice_id = v_invoice_id
    where id = v_header.source_quote_id
      and organization_id = p_organization_id;
    get diagnostics v_linked_rows = row_count;
    if v_linked_rows <> 1 then
      raise insufficient_privilege using message = 'source quote could not be linked';
    end if;
  end if;

  return v_invoice_id;
end;

