declare
  v_uid uuid := (select auth.uid());
  v_org_id uuid;
  v_owner_role_id uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  insert into public.organizations (
    name, slug, website,
    address_line1, address_line2, address_city, address_state, address_postal_code, address_country,
    socials,
    brand_primary_color, brand_secondary_color
  )
  values (
    p_name, p_slug, p_website,
    p_address_line1, p_address_line2, p_address_city, p_address_state, p_address_postal_code, p_address_country,
    p_socials,
    p_brand_primary_color, p_brand_secondary_color
  )
  returning id into v_org_id;

  select id into v_owner_role_id
  from public.roles
  where key = 'owner'
    and scope = 'organization'
    and organization_id is null
  limit 1;

  -- The creator becomes the organization owner. Bootstrapping the first seat
  -- is the one place a user legitimately grants itself a role, so bypass the
  -- assignment ceiling for this transaction.
  perform set_config('app.rbac_trusted_assignment', 'on', true);
  insert into public.organization_users (user_id, organization_id, role_id)
  values (v_uid, v_org_id, v_owner_role_id);

  perform public.seed_organization_document_templates(v_org_id, v_uid);
  perform public.seed_organization_vat_rates(v_org_id);

  return v_org_id;
end;

