  v_ids uuid[] := '{}';
begin
  if not public.has_org_permission(p_organization_id, 'organization.purchase-orders.create') then
    raise insufficient_privilege using message = 'purchase order create permission required';
  end if;

  create temporary table if not exists pg_temp.reorder_picks on commit drop as
    select * from public.inventory_reorder_suggestions(p_organization_id) limit 0;
  delete from pg_temp.reorder_picks;
  insert into pg_temp.reorder_picks
  select *
  from public.inventory_reorder_suggestions(p_organization_id) as suggestions
  where suggestions.supplier_id is not null
    and (p_variant_ids is null or suggestions.variant_id = any (p_variant_ids));

  for v_supplier in
