    from pg_temp.reorder_picks
    group by reorder_picks.supplier_id
  loop
    insert into public.purchase_orders (
      organization_id, number, supplier_id, currency, ship_to_location_id, created_by, updated_by
    )
    select p_organization_id,
      public.next_organization_number(p_organization_id, 'purchase_order'),
      v_supplier.supplier_id,
      v_supplier.currency,
      suppliers.default_inventory_location_id,
      auth.uid(),
      auth.uid()
    from public.suppliers
    where suppliers.id = v_supplier.supplier_id
    returning id into v_order_id;

    insert into public.purchase_order_lines (
      organization_id, purchase_order_id, product_id, variant_id, product_supplier_link_id,
      supplier_sku, title, quantity_ordered, unit_cost, vat_rate, position
    )
    select p_organization_id, v_order_id, reorder_picks.product_id, reorder_picks.variant_id,
      reorder_picks.product_supplier_link_id, reorder_picks.supplier_sku,
      left(
        case when coalesce(reorder_picks.variant_title, '') = '' then reorder_picks.product_name
          else reorder_picks.product_name || ' — ' || reorder_picks.variant_title end,
        300
      ),
