declare
  v_order record;
  v_po record;
  v_line record;
  v_item jsonb;
  v_quantity numeric(12, 3);
  v_shipment_id uuid;
  v_position integer := 0;
  v_header jsonb := coalesce(p_header, '{}'::jsonb);
  v_method public.order_delivery_method;
  v_default_method public.order_delivery_method := 'carrier';
  v_default_location uuid;
  v_address jsonb := '{}'::jsonb;
begin
  if p_lines is not null and jsonb_typeof(p_lines) <> 'array' then
    raise exception 'lines must be an array' using errcode = '22023';
  end if;

  if p_direction = 'inbound' then
    if not public.has_org_permission(p_organization_id, 'organization.purchase-orders.receive') then
      raise insufficient_privilege using message = 'purchase order receive permission required';
    end if;

    select purchase_orders.id, purchase_orders.status, purchase_orders.ship_to_location_id
    into v_po
    from public.purchase_orders
    where purchase_orders.id = p_purchase_order_id
      and purchase_orders.organization_id = p_organization_id
    for update;

    if not found then
      raise exception 'purchase order not found' using errcode = 'P0002';
    end if;

    if v_po.status not in ('sent', 'partially_received') then
      raise exception 'only sent purchase orders expect deliveries'
        using errcode = '22023', hint = 'purchase_order_not_sent';
    end if;

    v_default_location := v_po.ship_to_location_id;
  else
    if not public.has_org_permission(p_organization_id, 'organization.orders.fulfill') then
      raise insufficient_privilege using message = 'order fulfill permission required';
    end if;

    select orders.*
    into v_order
    from public.orders
    where orders.id = p_order_id
      and orders.organization_id = p_organization_id
    for update;

    if not found then
      raise exception 'order not found' using errcode = 'P0002';
    end if;

    if p_direction = 'outbound' and v_order.status <> 'confirmed' then
      raise exception 'only confirmed orders ship'
        using errcode = '22023', hint = 'order_not_shippable';
    end if;

    if p_direction = 'return' and v_order.status not in ('confirmed', 'completed') then
      raise exception 'only confirmed or completed orders take returns'
        using errcode = '22023', hint = 'order_not_returnable';
    end if;

    v_address := jsonb_build_object(
      'name', v_order.shipping_name,
      'line1', v_order.shipping_address_line1,
      'line2', v_order.shipping_address_line2,
      'postalCode', v_order.shipping_address_postal_code,
      'city', v_order.shipping_address_city,
      'country', v_order.shipping_address_country
    );
    if p_direction = 'outbound' then
      v_default_method := v_order.delivery_method;
    end if;
  end if;

  v_method := coalesce(
    nullif(v_header ->> 'deliveryMethod', '')::public.order_delivery_method,
    v_default_method
  );

  perform set_config('app.shipment_transition', 'on', true);

  insert into public.shipments (
    organization_id, number, direction, order_id, purchase_order_id, delivery_method,
    carrier, service, tracking_number, tracking_url, package_count, weight_grams,
    ship_to_name, address_line1, address_line2, address_postal_code, address_city,
    address_country, location_id, notes, created_by
  ) values (
    p_organization_id,
    public.next_organization_number(p_organization_id, 'shipment'),
    p_direction,
    case when p_direction = 'inbound' then null else p_order_id end,
    case when p_direction = 'inbound' then p_purchase_order_id else null end,
    v_method,
    nullif(btrim(v_header ->> 'carrier'), ''),
    nullif(btrim(v_header ->> 'service'), ''),
    nullif(btrim(v_header ->> 'trackingNumber'), ''),
    nullif(btrim(v_header ->> 'trackingUrl'), ''),
    coalesce(nullif(v_header ->> 'packageCount', '')::integer, 1),
    nullif(v_header ->> 'weightGrams', '')::integer,
    coalesce(nullif(btrim(v_header ->> 'shipToName'), ''), v_address ->> 'name'),
    coalesce(nullif(btrim(v_header ->> 'addressLine1'), ''), v_address ->> 'line1'),
    coalesce(nullif(btrim(v_header ->> 'addressLine2'), ''), v_address ->> 'line2'),
    coalesce(nullif(btrim(v_header ->> 'addressPostalCode'), ''), v_address ->> 'postalCode'),
    coalesce(nullif(btrim(v_header ->> 'addressCity'), ''), v_address ->> 'city'),
    coalesce(nullif(upper(btrim(v_header ->> 'addressCountry')), ''), v_address ->> 'country'),
    coalesce(nullif(v_header ->> 'locationId', '')::uuid, v_default_location),
    nullif(btrim(v_header ->> 'notes'), ''),
    auth.uid()
  )
  returning id into v_shipment_id;

  if p_direction = 'inbound' then
    for v_line in
      select purchase_order_lines.id, purchase_order_lines.product_id,
        purchase_order_lines.variant_id,
        greatest(
          purchase_order_lines.quantity_ordered - purchase_order_lines.quantity_cancelled
            - purchase_order_lines.quantity_received
            - coalesce((
              select sum(shipment_lines.quantity)
              from public.shipment_lines
              join public.shipments on shipments.id = shipment_lines.shipment_id
              where shipment_lines.purchase_order_line_id = purchase_order_lines.id
                and shipments.id <> v_shipment_id
                and shipments.status <> 'cancelled'
                and shipments.delivered_at is null
            ), 0),
          0
        ) as open_quantity
      from public.purchase_order_lines
      where purchase_order_lines.purchase_order_id = p_purchase_order_id
      order by purchase_order_lines.position, purchase_order_lines.id
    loop
      select element into v_item
      from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) as element
      where (element ->> 'purchaseOrderLineId')::uuid = v_line.id
      limit 1;

      v_quantity := case
        when p_lines is null then v_line.open_quantity
        else nullif(v_item ->> 'quantity', '')::numeric
      end;
      continue when coalesce(v_quantity, 0) <= 0;

      if v_quantity > v_line.open_quantity then
        raise exception 'shipment quantity exceeds the open quantity'
          using errcode = '22023', hint = 'shipment_over_quantity';
      end if;

      insert into public.shipment_lines (
        organization_id, shipment_id, purchase_order_line_id, product_id, variant_id,
        quantity, lot_number, serial_number, expires_on, position
      ) values (
        p_organization_id, v_shipment_id, v_line.id, v_line.product_id, v_line.variant_id,
        v_quantity, nullif(btrim(v_item ->> 'lotNumber'), ''),
        nullif(btrim(v_item ->> 'serialNumber'), ''),
        nullif(v_item ->> 'expiresOn', '')::date, v_position
      );
      v_position := v_position + 1;
    end loop;
  else
    for v_line in
      select order_lines.id, order_lines.product_id, order_lines.variant_id,
        case
          when p_direction = 'outbound' then
            order_lines.quantity - order_lines.quantity_cancelled - progress.fulfilled
            - coalesce((
              select sum(shipment_lines.quantity)
              from public.shipment_lines
              join public.shipments on shipments.id = shipment_lines.shipment_id
              where shipment_lines.order_line_id = order_lines.id
                and shipments.id <> v_shipment_id
                and shipments.direction = 'outbound'
                and shipments.status <> 'cancelled'
                and shipments.shipped_at is null
            ), 0)
          else
            progress.fulfilled - progress.returned
            - coalesce((
              select sum(shipment_lines.quantity)
              from public.shipment_lines
              join public.shipments on shipments.id = shipment_lines.shipment_id
              where shipment_lines.order_line_id = order_lines.id
                and shipments.id <> v_shipment_id
                and shipments.direction = 'return'
                and shipments.status <> 'cancelled'
                and shipments.delivered_at is null
            ), 0)
        end as open_quantity
      from public.order_lines
      join public.products on products.id = order_lines.product_id
      join public.order_line_progress(p_organization_id, p_order_id) as progress
        on progress.order_line_id = order_lines.id
      where order_lines.order_id = p_order_id
        and order_lines.line_type = 'product'
        and products.product_type = 'physical'
      order by order_lines.position, order_lines.id
    loop
      select element into v_item
      from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) as element
      where (element ->> 'orderLineId')::uuid = v_line.id
      limit 1;

      v_quantity := case
        when p_lines is null then greatest(v_line.open_quantity, 0)
        else nullif(v_item ->> 'quantity', '')::numeric
      end;
      continue when coalesce(v_quantity, 0) <= 0;

      if v_quantity > v_line.open_quantity then
        raise exception 'shipment quantity exceeds the open quantity'
          using errcode = '22023', hint = 'shipment_over_quantity';
      end if;

      insert into public.shipment_lines (
        organization_id, shipment_id, order_line_id, product_id, variant_id, quantity,
        lot_number, serial_number, expires_on, return_disposition, position
      ) values (
        p_organization_id, v_shipment_id, v_line.id, v_line.product_id, v_line.variant_id,
        v_quantity, nullif(btrim(v_item ->> 'lotNumber'), ''),
        nullif(btrim(v_item ->> 'serialNumber'), ''),
        nullif(v_item ->> 'expiresOn', '')::date,
        case
          when p_direction = 'return' then coalesce(
            nullif(v_item ->> 'returnDisposition', '')::public.shipment_return_disposition,
            'restock'
          )
        end,
        v_position
      );
      v_position := v_position + 1;
    end loop;
  end if;

  if v_position = 0 then
    raise exception 'nothing left to ship' using errcode = '22023', hint = 'shipment_empty';
  end if;

  perform set_config('app.shipment_transition', 'off', true);
  return v_shipment_id;
end;

