declare
  v_user_id uuid := auth.uid();
  v_task_id uuid;
  v_material public.task_materials%rowtype;
begin
  if v_user_id is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;

  if not public.has_org_permission(
    p_organization_id,
    'organization.tasks.update'
  ) then
    raise insufficient_privilege using message = 'task update permission required';
  end if;

  select task_materials.task_id
  into v_task_id
  from public.task_materials
  where task_materials.id = p_task_material_id
    and task_materials.organization_id = p_organization_id;

  if not found then
    raise exception 'task material not found in organization'
      using errcode = '23503';
  end if;

  perform 1
  from public.tasks
  where tasks.id = v_task_id
    and tasks.organization_id = p_organization_id
  for update;

  select task_materials.*
  into v_material
  from public.task_materials
  where task_materials.id = p_task_material_id
    and task_materials.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'task material not found in organization'
      using errcode = '23503';
  end if;

  if v_material.stock_state = 'consumed' then
    raise exception 'consumed task materials cannot be deleted until the task is reopened'
      using errcode = '23514';
  end if;

  perform set_config('app.allocation_release_reason', 'task material deleted', true);

  delete from public.task_materials
  where task_materials.id = p_task_material_id
    and task_materials.organization_id = p_organization_id;
end;

