declare
  v_first text := public.normalize_username_component(p_first_name);
  v_last text := public.normalize_username_component(p_last_name);
  v_full text := trim(coalesce(p_full_name, ''));
  v_base text;
  v_local text;
begin
  if v_first = '' and v_last = '' and v_full <> '' then
    v_first := public.normalize_username_component(split_part(v_full, ' ', 1));
    if position(' ' in v_full) > 0 then
      v_last := public.normalize_username_component(substring(v_full from position(' ' in v_full) + 1));
    end if;
  end if;

  if v_first <> '' and v_last <> '' then
    v_base := v_first || '_' || v_last;
  elsif v_first <> '' then
    v_base := v_first;
  elsif v_last <> '' then
    v_base := v_last;
  else
    v_local := split_part(coalesce(p_email, ''), '@', 1);
    v_base := public.normalize_username_component(v_local);
    if v_base = '' then
      v_base := 'user';
    end if;
  end if;

  if v_base !~ '^[a-z]' then
    v_base := 'u_' || v_base;
  end if;

  v_base := regexp_replace(v_base, '^_+|_+$', '', 'g');

  if char_length(v_base) < 3 then
    v_base := left(v_base || '_usr', 30);
  end if;

  return left(v_base, 30);
end;

