declare
  v_contract public.employee_contracts;
begin
  select * into v_contract
  from public.employee_contracts
  where employee_id = p_employee_id
    and starts_on <= p_date
    and (ends_on is null or ends_on >= p_date)
  order by starts_on desc
  limit 1;

  return v_contract;
end;

declare
  v_anchor date;
  v_has_week_two boolean;
begin
  select
    employees.schedule_cycle_anchor,
    exists (
      select 1 from public.employee_work_schedules
      where employee_id = employees.id and cycle_week = 2
    )
  into v_anchor, v_has_week_two
  from public.employees
  where employees.id = p_employee_id;

  if not coalesce(v_has_week_two, false) then
    return 1;
  end if;

  if v_anchor is null then
    return case when extract(week from p_date)::integer % 2 = 1 then 1 else 2 end;
  end if;

  return case when ((p_date - v_anchor) / 7) % 2 = 0 then 1 else 2 end;
end;

