declare
  v_contract public.employee_contracts;
  v_full_time numeric;
  v_hours numeric;
begin
  v_contract := public.employee_contract_on(p_employee_id, p_date);

  if v_contract.id is null or v_contract.pay_amount is null then
    return null;
  end if;

  select hr_settings.full_time_hours_per_week into v_full_time
  from public.hr_settings
  where organization_id = v_contract.organization_id;

  v_hours := coalesce(v_contract.hours_per_week, v_full_time, 40);

  return round(case v_contract.pay_basis
    when 'hourly' then v_contract.pay_amount
    when 'monthly' then v_contract.pay_amount * 12 / (52 * v_hours)
    when 'annual' then v_contract.pay_amount / (52 * v_hours)
    else null
  end, 4);
end;

