declare
  v_organization_id uuid;
  v_weekday smallint := extract(isodow from p_date)::smallint;
  v_cycle smallint;
  v_hours numeric;
begin
  select organization_id into v_organization_id
  from public.employees
  where id = p_employee_id;

  if v_organization_id is null then
    return 0;
  end if;

  if exists (select 1 from public.employee_work_schedules where employee_id = p_employee_id) then
    v_cycle := public.employee_cycle_week(p_employee_id, p_date);

    select coalesce(sum(
      extract(epoch from (
        case when ends_at > starts_at then ends_at - starts_at
        else (ends_at - starts_at) + interval '24 hours' end
      )) / 3600.0
    ), 0)
    into v_hours
    from public.employee_work_schedules
    where employee_id = p_employee_id
      and cycle_week = v_cycle
      and weekday = v_weekday;
  else
    select coalesce(sum(
      extract(epoch from (
        case when ends_at > starts_at then ends_at - starts_at
        else (ends_at - starts_at) + interval '24 hours' end
      )) / 3600.0
    ), 0)
    into v_hours
    from public.hr_default_schedule
    where organization_id = v_organization_id
      and cycle_week = 1
      and weekday = v_weekday;
  end if;

  return round(v_hours, 2);
end;

