declare
  v_drive_id uuid;
  v_node public.file_nodes;
  v_name text;
  v_suffix text;
begin
  if not exists (
    select 1
    from public.customers
    where id = p_customer_id
      and organization_id = p_organization_id
  ) then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;

  v_drive_id := public.ensure_customers_file_drive(p_organization_id);
  if v_drive_id is null then
    raise exception 'Customers drive is not available' using errcode = 'P0002';
  end if;

  select *
  into v_node
  from public.file_nodes
  where organization_id = p_organization_id
    and customer_id = p_customer_id
    and parent_id is null
    and deleted_at is null
  for update;

  v_name := left(
    coalesce(
      nullif(btrim(public.compute_customer_sort_name(p_customer_id)), ''),
      'Customer ' || p_customer_id::text
    ),
    240
  );
  if exists (
    select 1
    from public.file_nodes
    where drive_id = v_drive_id
      and parent_id is null
      and deleted_at is null
      and lower(name) = lower(v_name)
      and id is distinct from v_node.id
  ) then
    v_suffix := ' (' || p_customer_id::text || ')';
    v_name := left(v_name, greatest(240 - length(v_suffix), 1)) || v_suffix;
  end if;

  if v_node.id is not null then
    if v_node.name is distinct from v_name then
      update public.file_nodes
      set name = v_name
      where id = v_node.id
      returning * into v_node;
    end if;
    return v_node;
  end if;

  insert into public.file_nodes (
    organization_id,
    drive_id,
    kind,
    name,
    customer_id,
    created_by
  ) values (
    p_organization_id,
    v_drive_id,
    'folder',
    v_name,
    p_customer_id,
    (select auth.uid())
  )
  returning * into v_node;
  return v_node;
end;

