declare
  v_customer record;
  v_count integer := 0;
begin
  perform public.ensure_customers_file_drive(p_organization_id);
  for v_customer in
    select id
    from public.customers
    where organization_id = p_organization_id
  loop
    perform public.ensure_customer_file_folder(p_organization_id, v_customer.id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;

