declare
  v_vacation_type_id uuid;
  v_year integer := extract(year from (now() at time zone 'utc'))::integer;
begin
  insert into public.hr_settings (organization_id)
  values (p_organization_id)
  on conflict (organization_id) do nothing;

  if not exists (select 1 from public.hr_default_schedule where organization_id = p_organization_id) then
    insert into public.hr_default_schedule (organization_id, cycle_week, weekday, starts_at, ends_at)
    select p_organization_id, 1, weekday, time '08:00', time '17:00'
    from generate_series(1, 5) as weekday;
  end if;

  if not exists (select 1 from public.time_off_types where organization_id = p_organization_id) then
    insert into public.time_off_types (
      organization_id, name, category, color, icon_name, paid, requires_approval,
      deducts_balance, requires_attachment, position
    )
    values
      (p_organization_id, 'Vacation', 'vacation', '#16a34a', 'Beach02Icon', true, null, true, false, 0),
      (p_organization_id, 'Sick leave', 'sick', '#dc2626', 'MedicineBottle01Icon', true, false, false, false, 1),
      (p_organization_id, 'Special leave', 'special', '#7c3aed', 'Calendar03Icon', true, null, false, false, 2),
      (p_organization_id, 'Unpaid leave', 'unpaid', '#64748b', 'MoneyNotFound01Icon', false, null, false, false, 3),
      (p_organization_id, 'Compensatory time', 'compensatory', '#0891b2', 'Clock01Icon', true, null, true, false, 4);

    select id into v_vacation_type_id
    from public.time_off_types
    where organization_id = p_organization_id and category = 'vacation'
    order by position
    limit 1;

    insert into public.time_off_policies (
      organization_id, time_off_type_id, name, annual_hours, accrual_method,
      carryover_max_hours, carryover_expires_after_months, is_default
    )
    values (p_organization_id, v_vacation_type_id, 'Standard vacation', 200, 'upfront', 200, 6, true);
  end if;

  if not exists (select 1 from public.expense_categories where organization_id = p_organization_id) then
    insert into public.expense_categories (organization_id, name, default_vat_rate, icon_name, position)
    values
      (p_organization_id, 'Travel', 9, 'Car01Icon', 0),
      (p_organization_id, 'Meals', 9, 'Restaurant01Icon', 1),
      (p_organization_id, 'Office supplies', 21, 'Stapler01Icon', 2),
      (p_organization_id, 'Software', 21, 'SoftwareIcon', 3),
      (p_organization_id, 'Tools and materials', 21, 'Wrench01Icon', 4),
      (p_organization_id, 'Other', 21, 'Invoice01Icon', 5);
  end if;

  perform public.seed_public_holidays(p_organization_id, v_year);
  perform public.seed_public_holidays(p_organization_id, v_year + 1);
end;

declare
  v_promotion public.promotions;
  v_reason text;
begin
  if auth.uid() is not null and not public.has_any_org_permission(
    p_organization_id,
    array[
      'organization.quotes.create', 'organization.quotes.update',
      'organization.orders.create', 'organization.orders.update',
      'organization.invoices.create', 'organization.invoices.update',
      'organization.promotions.view'
    ]
  ) then
    raise insufficient_privilege using message = 'promotion access required';
  end if;

  select * into v_promotion
  from public.promotions
  where promotions.organization_id = p_organization_id
    and (
      (p_promotion_id is not null and promotions.id = p_promotion_id)
      or (p_promotion_id is null and p_code is not null and lower(promotions.code) = lower(btrim(p_code)))
    );

  if not found then
    return jsonb_build_object('valid', false, 'reason', 'not_found', 'promotion', null);
  end if;

  v_reason := public.promotion_rejection(
    v_promotion.id, p_subject_type, p_customer_id, p_subtotal, p_quantity, p_subject_id, true
  );

  return jsonb_build_object(
    'valid', v_reason is null,
    'reason', v_reason,
    'promotion', jsonb_build_object(
      'id', v_promotion.id,
      'name', v_promotion.name,
      'code', v_promotion.code,
      'kind', v_promotion.kind,
      'value', v_promotion.value,
      'currency', v_promotion.currency,
      'appliesTo', v_promotion.applies_to
    )
  );
end;

