declare
  v_backorder record;
  v_got numeric(12, 3);
  v_filled numeric(12, 3) := 0;
  v_task_ids uuid[] := '{}';
  v_task_id uuid;
begin
  for v_backorder in
    select inventory_allocations.id, inventory_allocations.product_id,
      inventory_allocations.quantity, inventory_allocations.task_material_id,
      inventory_allocations.order_line_id
    from public.inventory_allocations
    where inventory_allocations.organization_id = p_organization_id
      and inventory_allocations.variant_id = p_variant_id
      and inventory_allocations.state = 'backordered'
    order by inventory_allocations.created_at, inventory_allocations.id
    for update
  loop
    v_got := public.allocate_product_stock(
      p_organization_id,
      v_backorder.product_id,
      v_backorder.quantity,
      v_backorder.task_material_id,
      null,
      null,
      'backorder filled',
      null,
      null,
      auth.uid(),
      p_location_id,
      v_backorder.order_line_id
    );
    exit when v_got <= 0;

    if v_got >= v_backorder.quantity then
      delete from public.inventory_allocations where inventory_allocations.id = v_backorder.id;
    else
      update public.inventory_allocations
      set quantity = quantity - v_got
      where inventory_allocations.id = v_backorder.id;
    end if;
    v_filled := v_filled + v_got;

    if v_backorder.task_material_id is not null then
      select task_materials.task_id into v_task_id
      from public.task_materials
      where task_materials.id = v_backorder.task_material_id;
      v_task_ids := array_append(v_task_ids, v_task_id);
    end if;

    exit when v_got < v_backorder.quantity;
  end loop;

  foreach v_task_id in array coalesce(
    (select array_agg(distinct task_id) from unnest(v_task_ids) as task_id),
    '{}'::uuid[]
  )
  loop
    perform public.apply_task_parts_hold(p_organization_id, v_task_id);
  end loop;

  return v_filled;
end;

