declare
  v_item public.file_copy_operation_items;
  v_operation public.file_copy_operations;
  v_source_version public.file_versions;
  v_target_version public.file_versions;
begin
  select * into v_item
  from public.file_copy_operation_items
  where id = p_item_id
  for update;
  if v_item.id is null then
    raise exception 'Copy item not found' using errcode = 'P0002';
  end if;
  select * into v_operation
  from public.file_copy_operations
  where id = v_item.operation_id
  for update;
  if v_operation.created_by <> (select auth.uid()) then
    raise exception 'Copy item finalization is not allowed' using errcode = '42501';
  end if;
  if v_item.status = 'completed' then
    return v_item;
  end if;
  select * into v_source_version
  from public.file_versions
  where id = v_item.source_version_id;
  if v_source_version.id is null then
    raise exception 'Source version not found' using errcode = 'P0002';
  end if;

  select * into v_target_version
  from public.file_versions
  where storage_bucket = p_storage_bucket and storage_path = p_storage_path;
  if v_target_version.id is null then
    insert into public.file_versions (
      organization_id, drive_id, node_id, version_number, media_type, byte_size,
      storage_bucket, storage_path, checksum, etag, source_modified_at, created_by,
      retention_until
    )
    select
      v_operation.organization_id, v_operation.destination_drive_id, v_item.target_node_id,
      1, media_type, byte_size, p_storage_bucket, p_storage_path, checksum, etag,
      source_modified_at, v_operation.created_by,
      (now() at time zone 'utc')
        + make_interval(days => public.get_file_retention_days(v_operation.organization_id))
    from public.file_versions
    where id = v_item.source_version_id
    returning * into v_target_version;
  end if;

  update public.file_nodes
  set current_version_id = v_target_version.id
  where id = v_item.target_node_id;
  update public.file_copy_operation_items
  set
    target_version_id = v_target_version.id,
    target_storage_path = p_storage_path,
    status = 'completed',
    error_message = null
  where id = v_item.id
  returning * into v_item;
  update public.file_copy_operations
  set
    status = case
      when not exists (
        select 1 from public.file_copy_operation_items
        where operation_id = v_operation.id and status <> 'completed'
      ) then 'completed'
      else 'copying'
    end,
    completed_items = (
      select count(*) from public.file_copy_operation_items
      where operation_id = v_operation.id and status = 'completed'
    ),
    completed_at = case
      when not exists (
        select 1 from public.file_copy_operation_items
        where operation_id = v_operation.id and status <> 'completed'
      ) then (now() at time zone 'utc')
      else null
    end,
    error_message = null
  where id = v_operation.id;
  return v_item;
end;

