declare
  v_reservation public.file_upload_reservations;
  v_node public.file_nodes;
  v_version public.file_versions;
  v_quota bigint;
  v_stored bigint;
  v_reserved bigint;
begin
  select * into v_reservation
  from public.file_upload_reservations
  where id = p_reservation_id
  for update;
  if v_reservation.id is null then
    raise exception 'Upload reservation not found' using errcode = 'P0002';
  end if;
  if v_reservation.created_by <> (select auth.uid()) then
    raise exception 'Upload finalization is not allowed' using errcode = '42501';
  end if;
  if v_reservation.status = 'finalized' then
    return v_reservation;
  end if;
  if v_reservation.status not in ('reserved', 'uploaded')
    or v_reservation.expires_at <= (now() at time zone 'utc')
    or p_actual_bytes < 0 then
    raise exception 'Upload reservation is no longer finalizable' using errcode = '23514';
  end if;

  perform 1
  from public.file_storage_settings
  where organization_id = v_reservation.organization_id
  for update;
  v_quota := public.get_file_storage_quota_bytes(v_reservation.organization_id);
  select coalesce(sum(byte_size), 0) into v_stored
  from public.file_versions
  where organization_id = v_reservation.organization_id;
  select coalesce(sum(expected_bytes), 0) into v_reserved
  from public.file_upload_reservations
  where organization_id = v_reservation.organization_id
    and id <> v_reservation.id
    and status in ('reserved', 'uploaded')
    and expires_at > (now() at time zone 'utc');
  if v_quota is not null and v_stored + v_reserved + p_actual_bytes > v_quota then
    raise exception 'File storage quota exceeded' using errcode = 'P0001';
  end if;

  if v_reservation.node_id is null then
    insert into public.file_nodes (
      organization_id, drive_id, parent_id, kind, name, created_by
    ) values (
      v_reservation.organization_id, v_reservation.drive_id, v_reservation.parent_id,
      'file', v_reservation.file_name, (select auth.uid())
    )
    returning * into v_node;
    update public.file_upload_reservations set node_id = v_node.id
    where id = v_reservation.id;
  else
    select * into v_node from public.file_nodes where id = v_reservation.node_id;
  end if;

  v_version := public.create_file_version(
    v_node.id, v_reservation.media_type, p_actual_bytes,
    v_reservation.storage_bucket, v_reservation.storage_path, p_checksum, p_etag, null
  );
  update public.file_upload_reservations
  set
    status = 'finalized',
    actual_bytes = p_actual_bytes,
    checksum = p_checksum,
    etag = p_etag,
    finalized_version_id = v_version.id,
    finalized_at = (now() at time zone 'utc')
  where id = v_reservation.id
  returning * into v_reservation;
  return v_reservation;
end;

