CREATE OR REPLACE FUNCTION public.fulfill_digital_order(p_organization_id uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order record;
  v_line record;
  v_key record;
  v_shipment_id uuid;
  v_position integer := 0;
  v_needed integer;
  v_count integer;
  v_delivered numeric(12, 3);
  v_keys jsonb := '[]'::jsonb;
  v_files jsonb := '[]'::jsonb;
  v_short jsonb := '[]'::jsonb;
  v_order_status public.order_status;
  v_staff jsonb := '[]'::jsonb;
begin
  if auth.uid() is not null
    and not public.has_org_permission(p_organization_id, 'organization.orders.fulfill')
  then
    raise insufficient_privilege using message = 'order fulfill permission required';
  end if;

  select orders.id, orders.status, orders.customer_id,
    orders.number_prefix || lpad(orders.number::text, 4, '0') as reference,
    coalesce(nullif(btrim(orders.buyer_email), ''), nullif(btrim(customers.billing_email), ''))
      as recipient,
    coalesce(
      nullif(btrim(orders.buyer_name), ''), customers.billing_name, customers.company_name,
      customers.sort_name
    ) as customer_name
  into v_order
  from public.orders
  join public.customers on customers.id = orders.customer_id
  where orders.id = p_order_id
    and orders.organization_id = p_organization_id
  for update of orders;

  if not found then
    raise exception 'order not found' using errcode = 'P0002';
  end if;

  if v_order.status <> 'confirmed' then
    raise exception 'only confirmed orders are fulfilled'
      using errcode = '22023', hint = 'order_not_shippable';
  end if;

  for v_line in
    select order_lines.id, order_lines.title, order_lines.product_id, order_lines.variant_id,
      products.digital_delivery,
      order_lines.quantity - order_lines.quantity_cancelled - coalesce((
        select sum(shipment_lines.quantity)
        from public.shipment_lines
        join public.shipments on shipments.id = shipment_lines.shipment_id
        where shipment_lines.order_line_id = order_lines.id
          and shipments.direction = 'outbound'
          and shipments.status <> 'cancelled'
      ), 0) as open_quantity
    from public.order_lines
    join public.products on products.id = order_lines.product_id
    where order_lines.order_id = p_order_id
      and order_lines.line_type = 'product'
      and products.product_type = 'digital'
      and products.digital_delivery in ('file', 'license_key')
    order by order_lines.position, order_lines.id
  loop
    continue when v_line.open_quantity <= 0;

    if v_line.digital_delivery = 'license_key' then
      v_needed := ceil(v_line.open_quantity)::integer;
      v_count := 0;

      for v_key in
        select product_license_keys.id, product_license_keys.license_key
        from public.product_license_keys
        where product_license_keys.organization_id = p_organization_id
          and product_license_keys.product_id = v_line.product_id
          and (
            product_license_keys.variant_id is null
            or product_license_keys.variant_id = v_line.variant_id
          )
          and product_license_keys.order_line_id is null
          and product_license_keys.revoked_at is null
        order by (product_license_keys.variant_id is null), product_license_keys.created_at,
          product_license_keys.id
        limit v_needed
        for update skip locked
      loop
        update public.product_license_keys
        set order_line_id = v_line.id, assigned_at = now()
        where product_license_keys.id = v_key.id;

        insert into public.order_digital_grants (organization_id, order_line_id, license_key_id)
        values (p_organization_id, v_line.id, v_key.id);

        v_keys := v_keys || jsonb_build_object('title', v_line.title, 'licenseKey', v_key.license_key);
        v_count := v_count + 1;
      end loop;

      v_delivered := least(v_count::numeric, v_line.open_quantity);
    else
      insert into public.order_digital_grants (organization_id, order_line_id, digital_file_id)
      select p_organization_id, v_line.id, product_digital_files.id
      from public.product_digital_files
      where product_digital_files.product_id = v_line.product_id
        and (
          product_digital_files.variant_id is null
          or product_digital_files.variant_id = v_line.variant_id
        )
      on conflict (order_line_id, digital_file_id) where digital_file_id is not null do nothing;

      if exists (
        select 1 from public.order_digital_grants
        where order_digital_grants.order_line_id = v_line.id
          and order_digital_grants.digital_file_id is not null
          and order_digital_grants.revoked_at is null
      ) then
        v_delivered := v_line.open_quantity;
        v_files := v_files || coalesce((
          select jsonb_agg(jsonb_build_object('title', v_line.title, 'fileName', product_digital_files.file_name)
            order by product_digital_files.position, product_digital_files.id)
          from public.order_digital_grants
          join public.product_digital_files
            on product_digital_files.id = order_digital_grants.digital_file_id
          where order_digital_grants.order_line_id = v_line.id
            and order_digital_grants.revoked_at is null
        ), '[]'::jsonb);
      else
        v_delivered := 0;
      end if;
    end if;

    if v_delivered < v_line.open_quantity then
      v_short := v_short || jsonb_build_object(
        'orderLineId', v_line.id,
        'title', v_line.title,
        'missing', v_line.open_quantity - v_delivered
      );
    end if;

    continue when v_delivered <= 0;

    perform set_config('app.shipment_transition', 'on', true);
    if v_shipment_id is null then
      insert into public.shipments (
        organization_id, number, direction, order_id, delivery_method, status,
        shipped_at, delivered_at, status_occurred_at, ship_to_name, created_by
      ) values (
        p_organization_id,
        public.next_organization_number(p_organization_id, 'shipment'),
        'outbound', p_order_id, 'digital', 'delivered', now(), now(), now(),
        v_order.customer_name, auth.uid()
      )
      returning id into v_shipment_id;
    end if;

    insert into public.shipment_lines (
      organization_id, shipment_id, order_line_id, product_id, variant_id, quantity, position
    ) values (
      p_organization_id, v_shipment_id, v_line.id, v_line.product_id, v_line.variant_id,
      v_delivered, v_position
    );
    perform set_config('app.shipment_transition', 'off', true);
    v_position := v_position + 1;
  end loop;

  v_order_status := public.refresh_order_status(p_organization_id, p_order_id);

  if jsonb_array_length(v_short) > 0 then
    select coalesce(jsonb_agg(distinct staff.user_id), '[]'::jsonb)
    into v_staff
    from (
      select orders.created_by as user_id
      from public.orders
      where orders.id = p_order_id and orders.created_by is not null
      union
      select organization_users.user_id
      from public.organization_users
      join public.permissions on permissions.key = 'organization.orders.fulfill'
        and permissions.scope = 'organization'
      left join public.organization_permission_overrides overrides
        on overrides.organization_id = p_organization_id
        and overrides.role_id = organization_users.role_id
        and overrides.permission_id = permissions.id
      where organization_users.organization_id = p_organization_id
        and coalesce(overrides.granted, exists (
          select 1 from public.role_permissions
          where role_permissions.role_id = organization_users.role_id
            and role_permissions.permission_id = permissions.id
        ))
    ) staff;
  end if;

  return jsonb_build_object(
    'orderId', p_order_id,
    'orderStatus', v_order_status,
    'orderReference', v_order.reference,
    'customerId', v_order.customer_id,
    'customerName', v_order.customer_name,
    'recipient', v_order.recipient,
    'shipmentId', v_shipment_id,
    'licenseKeys', v_keys,
    'files', v_files,
    'short', v_short,
    'staffUserIds', v_staff
  );
end;
$function$

functions.definition:
declare
  v_user_id uuid := (select auth.uid());
  v_organization public.organizations%rowtype;
  v_permissions text[] := '{}'::text[];
  v_permission_candidates constant text[] := array[
    'organization.agenda.view',
    'organization.assets.view',
    'organization.chats.create',
    'organization.chats.view',
    'organization.customers.view',
    'organization.integrations.manage',
    'organization.invoices.view',
    'organization.knowledge.view',
    'organization.members.invite',
    'organization.members.view',
    'organization.products.view',
    'organization.quotes.view',
    'organization.tasks.view',
    'organization.teams.view',
    'organization.workflows.view'
  ]::text[];
  v_snapshot jsonb;
  v_state jsonb := '{}'::jsonb;
  v_catalogs jsonb := jsonb_build_object(
    'knowledgeCollections', '[]'::jsonb,
    'workflows', '[]'::jsonb
  );
  v_refreshed_at timestamptz;
  v_refresh_needed boolean := true;
  v_suggestions_model text;
  v_mine_task_total bigint := 0;
  v_mine_task_samples jsonb := '[]'::jsonb;
begin
  if v_user_id is null then
    raise exception 'authentication required'
      using errcode = '28000';
  end if;

  if p_surface not in ('page', 'panel') then
    raise exception 'invalid suggestion surface'
      using errcode = '22023';
  end if;

  if p_route_domain not in (
    'access',
    'agenda',
    'assets',
    'channels',
    'customers',
    'dashboard',
    'generic',
    'inbox',
    'integrations',
    'invoices',
    'knowledge',
    'quotes',
    'tasks',
    'teams',
    'workflows'
  ) then
    raise exception 'invalid suggestion route domain'
      using errcode = '22023';
  end if;

  select organizations.*
  into v_organization
  from public.organizations
  where organizations.slug = p_organization_slug
    and organizations.disabled_at is null;

  if not found then
    raise exception 'organization not found'
      using errcode = 'P0002';
  end if;

  select public.authorize_scope_batch(
    'organization',
    v_organization.id,
    v_permission_candidates
  )
  into v_permissions;

  if not (
    'organization.chats.view' = any(v_permissions)
    or 'organization.chats.create' = any(v_permissions)
  ) then
    raise exception 'chat suggestions are not authorized'
      using errcode = '42501';
  end if;

  select
    chat_suggestion_snapshots.snapshot,
    chat_suggestion_snapshots.refreshed_at
  into
    v_snapshot,
    v_refreshed_at
  from public.chat_suggestion_snapshots
  where chat_suggestion_snapshots.organization_id = v_organization.id;

  if v_snapshot is null then
    select ai_model_use_defaults.model_id
    into v_suggestions_model
    from public.ai_model_use_defaults
    join public.ai_model_settings
      on ai_model_settings.model_id = ai_model_use_defaults.model_id
      and ai_model_settings.enabled
    where ai_model_use_defaults.use_case = 'suggestions';

    v_snapshot := jsonb_build_object(
      'catalogs',
      v_catalogs,
      'inferenceRegion',
      v_organization.ai_inference_region,
      'organizationId',
      v_organization.id,
      'organizationName',
      v_organization.name,
      'state',
      '{}'::jsonb,
      'suggestionsModel',
      coalesce(v_suggestions_model, 'openai/gpt-5.4')
    );
  else
    v_refresh_needed := v_refreshed_at <= (
      (now() at time zone 'utc') - interval '5 minutes'
    );
  end if;

  if (
    p_surface = 'page'
    or p_route_domain in ('agenda', 'tasks')
  ) and 'organization.agenda.view' = any(v_permissions) then
    v_state := v_state || jsonb_build_object(
      'agenda',
      coalesce(
        v_snapshot -> 'state' -> 'agenda',
        jsonb_build_object(
          'confirmedTodayTotal', 0,
          'conflictTotal', 0,
          'riskSamples', '[]'::jsonb,
          'suggestedTodayTotal', 0,
          'unscheduledTotal', 0
        )
      )
      || jsonb_build_object(
        'riskSamples',
        coalesce(
          (
            select jsonb_agg(
              case
                when 'organization.tasks.view' = any(v_permissions) then
                  risk_sample.value - 'agendaLabel' - 'taskDerived'
                when coalesce((risk_sample.value ->> 'taskDerived')::boolean, false) then
                  (
                    risk_sample.value
                    || jsonb_build_object('label', risk_sample.value ->> 'agendaLabel')
                  ) - 'agendaLabel' - 'taskDerived' - 'status'
                else
                  (
                    risk_sample.value
                    || jsonb_build_object('label', risk_sample.value ->> 'agendaLabel')
                  ) - 'agendaLabel' - 'taskDerived'
              end
            )
            from jsonb_array_elements(
              coalesce(v_snapshot -> 'state' -> 'agenda' -> 'riskSamples', '[]'::jsonb)
            ) as risk_sample(value)
            where 'organization.tasks.view' = any(v_permissions)
              or jsonb_typeof(risk_sample.value -> 'agendaLabel') = 'string'
          ),
          '[]'::jsonb
        )
      )
      || case
        when 'organization.tasks.view' = any(v_permissions) then '{}'::jsonb
        else jsonb_build_object('unscheduledTotal', 0)
      end
    );
  end if;

  if (
    p_surface = 'page'
    or p_route_domain in ('agenda', 'tasks')
  ) and 'organization.tasks.view' = any(v_permissions) then
    select count(*)
    into v_mine_task_total
    from public.task_assignees
    join public.tasks
      on tasks.id = task_assignees.task_id
      and tasks.organization_id = task_assignees.organization_id
    where task_assignees.organization_id = v_organization.id
      and task_assignees.user_id = v_user_id
      and tasks.parent_task_id is null
      and tasks.archived_at is null
      and tasks.status <> 'done';

    select coalesce(jsonb_agg(actor_tasks.sample), '[]'::jsonb)
    into v_mine_task_samples
    from (
      select jsonb_build_object(
        'label',
        left(
          concat(v_organization.task_number_prefix, tasks.number, ' ', tasks.title),
          160
        ),
        'status',
        tasks.priority::text
      ) as sample
      from public.task_assignees
      join public.tasks
        on tasks.id = task_assignees.task_id
        and tasks.organization_id = task_assignees.organization_id
      where task_assignees.organization_id = v_organization.id
        and task_assignees.user_id = v_user_id
        and tasks.parent_task_id is null
        and tasks.archived_at is null
        and tasks.status <> 'done'
      order by
        case tasks.priority
          when 'urgent' then 0
          when 'high' then 1
          when 'medium' then 2
          when 'low' then 3
        end,
        tasks.due_at nulls last,
        tasks.updated_at desc
      limit 5
    ) as actor_tasks;

    v_state := v_state || jsonb_build_object(
      'tasks',
      coalesce(
        v_snapshot -> 'state' -> 'tasks',
        jsonb_build_object(
          'orgSamples', '[]'::jsonb,
          'orgTotal', 0,
          'urgentSamples', '[]'::jsonb
        )
      )
      || jsonb_build_object(
        'mineSamples', v_mine_task_samples,
        'mineTotal', v_mine_task_total
      )
    );
  end if;

  if (
    p_surface = 'page'
    or p_route_domain in ('customers', 'assets', 'quotes')
  ) and 'organization.customers.view' = any(v_permissions) then
    v_state := v_state || jsonb_build_object(
      'customers',
      coalesce(
        v_snapshot -> 'state' -> 'customers',
        jsonb_build_object('samples', '[]'::jsonb, 'total', 0)
      )
      || jsonb_build_object(
        'samples',
        coalesce(
          (
            select jsonb_agg(
              customer_sample.value
              - array_remove(
                array[
                  case
                    when 'organization.quotes.view' <> all(v_permissions)
                      then 'quoteCount'
                    else null
                  end,
                  case
                    when 'organization.tasks.view' <> all(v_permissions)
                      then 'taskCount'
                    else null
                  end
                ]::text[],
                null
              )
            )
            from jsonb_array_elements(
              coalesce(v_snapshot -> 'state' -> 'customers' -> 'samples', '[]'::jsonb)
            ) as customer_sample(value)
          ),
          '[]'::jsonb
        )
      )
    );
  end if;

  if (
    p_surface = 'page'
    or p_route_domain = 'quotes'
  ) and 'organization.quotes.view' = any(v_permissions) then
    v_state := v_state || jsonb_build_object(
      'quotes',
      coalesce(
        v_snapshot -> 'state' -> 'quotes',
        jsonb_build_object(
          'draftSamples', '[]'::jsonb,
          'draftTotal', 0,
          'sentSamples', '[]'::jsonb,
          'sentTotal', 0
        )
      )
    );
  end if;

  if (
    p_surface = 'page'
    or p_route_domain = 'assets'
  ) and (
    'organization.assets.view' = any(v_permissions)
    or 'organization.products.view' = any(v_permissions)
  ) then
    v_state := v_state || jsonb_build_object(
      'assets',
      coalesce(
        v_snapshot -> 'state' -> 'assets',
        jsonb_build_object(
          'customerAssetSamples', '[]'::jsonb,
          'customerAssetTotal', 0,
          'inventoryIssueSamples', '[]'::jsonb,
          'productSamples', '[]'::jsonb,
          'productTotal', 0
        )
      )
      || case
        when 'organization.assets.view' = any(v_permissions) then jsonb_build_object(
          'customerAssetSamples',
          coalesce(
            (
              select jsonb_agg(
                (
                  asset_sample.value
                  || case
                    when 'organization.products.view' = any(v_permissions) then '{}'::jsonb
                    else jsonb_build_object('label', asset_sample.value ->> 'assetLabel')
                  end
                ) - 'assetLabel'
              )
              from jsonb_array_elements(
                coalesce(
                  v_snapshot -> 'state' -> 'assets' -> 'customerAssetSamples',
                  '[]'::jsonb
                )
              ) as asset_sample(value)
              where 'organization.products.view' = any(v_permissions)
                or jsonb_typeof(asset_sample.value -> 'assetLabel') = 'string'
            ),
            '[]'::jsonb
          ),
          'inventoryIssueSamples',
          case
            when 'organization.products.view' = any(v_permissions)
              then coalesce(
                v_snapshot -> 'state' -> 'assets' -> 'inventoryIssueSamples',
                '[]'::jsonb
              )
            else '[]'::jsonb
          end
        )
        else jsonb_build_object(
          'customerAssetSamples', '[]'::jsonb,
          'customerAssetTotal', 0,
          'inventoryIssueSamples', '[]'::jsonb
        )
      end
      || case
        when 'organization.products.view' = any(v_permissions) then '{}'::jsonb
        else jsonb_build_object(
          'productSamples', '[]'::jsonb,
          'productTotal', 0
        )
      end
    );
  end if;

  if (
    p_surface = 'page'
    or p_route_domain in ('access', 'teams')
  ) and (
    'organization.members.view' = any(v_permissions)
    or 'organization.members.invite' = any(v_permissions)
    or 'organization.teams.view' = any(v_permissions)
  ) then
    v_state := v_state || jsonb_build_object(
      'access',
      coalesce(
        v_snapshot -> 'state' -> 'access',
        jsonb_build_object(
          'memberTotal', 0,
          'pendingInvitationTotal', 0,
          'teamTotal', 0
        )
      )
      || case
        when 'organization.members.view' = any(v_permissions) then '{}'::jsonb
        else jsonb_build_object('memberTotal', 0)
      end
      || case
        when 'organization.members.invite' = any(v_permissions) then '{}'::jsonb
        else jsonb_build_object('pendingInvitationTotal', 0)
      end
      || case
        when 'organization.teams.view' = any(v_permissions) then '{}'::jsonb
        else jsonb_build_object('teamTotal', 0)
      end
    );
  end if;

  if (
    p_surface = 'page'
    or p_route_domain in ('channels', 'integrations')
  ) and 'organization.integrations.manage' = any(v_permissions) then
    v_state := v_state || jsonb_build_object(
      'channels',
      coalesce(
        v_snapshot -> 'state' -> 'channels',
        jsonb_build_object(
          'activeTotal', 0,
          'draftTotal', 0,
          'errorSamples', '[]'::jsonb,
          'total', 0
        )
      )
    );
  end if;

  if p_surface = 'panel'
    and p_route_domain = 'knowledge'
    and 'organization.knowledge.view' = any(v_permissions) then
    v_catalogs := jsonb_set(
      v_catalogs,
      '{knowledgeCollections}',
      coalesce(
        (
          select jsonb_agg(actor_knowledge.item)
          from (
            select jsonb_build_object(
              'description',
              left(collection.description, 500),
              'name',
              left(collection.name, 160)
            ) as item
            from public.knowledge_collections as collection
            where (
                collection.organization_id = v_organization.id
                or collection.organization_id is null
              )
              and collection.visibility <> 'disabled'
              and public.can_read_knowledge_collection_row(
                collection.id,
                collection.organization_id,
                collection.visibility,
                collection.created_by
              )
            order by collection.retrieval_priority, collection.name
            limit 6
          ) as actor_knowledge
        ),
        '[]'::jsonb
      )
    );
  end if;

  if p_surface = 'panel'
    and p_route_domain = 'workflows'
    and 'organization.workflows.view' = any(v_permissions) then
    v_catalogs := jsonb_set(
      v_catalogs,
      '{workflows}',
      coalesce(
        (
          select jsonb_agg(actor_workflows.item)
          from (
            select jsonb_build_object(
              'description',
              left(definition.description, 500),
              'name',
              left(definition.name, 160)
            ) as item
            from public.workflow_definitions as definition
            where (
                definition.organization_id = v_organization.id
                or definition.organization_id is null
              )
              and definition.status = 'published'
              and definition.archived_at is null
              and public.can_read_workflow_definition_row(
                definition.id,
                definition.owner_scope,
                definition.organization_id,
                definition.status,
                definition.visibility,
                definition.created_by
              )
            order by definition.updated_at desc
            limit 6
          ) as actor_workflows
        ),
        '[]'::jsonb
      )
    );
  end if;

  return jsonb_build_object(
    'catalogs',
    v_catalogs,
    'inferenceRegion',
    coalesce(
      v_snapshot ->> 'inferenceRegion',
      v_organization.ai_inference_region::text
    ),
    'organizationId',
    v_organization.id,
    'organizationName',
    v_organization.name,
    'permissionFingerprint',
    md5(array_to_string(v_permissions, E'\n')),
    'permissionKeys',
    to_jsonb(v_permissions),
    'refreshedAt',
    case when v_refreshed_at is null then null else to_jsonb(v_refreshed_at) end,
    'refreshNeeded',
    v_refresh_needed,
    'snapshotStatus',
    case
      when v_refreshed_at is null then 'missing'
      when v_refresh_needed then 'stale'
      else 'fresh'
    end,
    'state',
    v_state,
    'suggestionsModel',
    v_snapshot ->> 'suggestionsModel',
    'userId',
    v_user_id
  );
end;

