declare
  v_org_id uuid;
  v_product public.products%rowtype;
  v_org jsonb;
  v_brand jsonb;
  v_images jsonb;
begin
  if p_org_slug is null or p_product_id is null then
    return null;
  end if;

  select o.id into v_org_id
  from public.organizations o
  where lower(o.slug) = lower(p_org_slug)
  limit 1;

  if v_org_id is null then
    return null;
  end if;

  select * into v_product
  from public.products
  where id = p_product_id
    and organization_id = v_org_id
    and status <> 'archived'
  limit 1;

  if v_product.id is null then
    return null;
  end if;

  select jsonb_build_object(
    'id', o.id,
    'name', o.name,
    'slug', o.slug,
    'logo_path', o.logo_path,
    'brand_primary_color', o.brand_primary_color,
    'brand_secondary_color', o.brand_secondary_color
  )
  into v_org
  from public.organizations o
  where o.id = v_product.organization_id;

  if v_product.brand_id is not null then
    select jsonb_build_object(
      'id', b.id,
      'name', b.name,
      'slug', b.slug
    )
    into v_brand
    from public.brands b
    where b.id = v_product.brand_id;
  else
    v_brand := null;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', i.id,
        'storage_path', i.storage_path,
        'alt_text', i.alt_text,
        'position', i.position
      )
      order by i.position
    ),
    '[]'::jsonb
  )
  into v_images
  from public.asset_images i
  where i.product_id = v_product.id;

  -- Customer-safe product payload only — never purchase price or suppliers.
  return jsonb_build_object(
    'product', jsonb_build_object(
      'id', v_product.id,
      'organization_id', v_product.organization_id,
      'name', v_product.name,
      'slug', v_product.slug,
      'description', v_product.description,
      'manufacturer', v_product.manufacturer,
      'model', v_product.model,
      'sku', v_product.sku,
      'ean', v_product.ean,
      'default_selling_price', v_product.default_selling_price,
      'currency', v_product.currency
    ),
    'brand', v_brand,
    'images', v_images,
    'organization', v_org
  );
end;

