declare
  v_feed public.time_off_feeds%rowtype;
  v_organization_name text;
  v_team_name text;
  v_absences jsonb;
begin
  select * into v_feed from public.time_off_feeds where time_off_feeds.token = p_token;
  if not found then
    return null;
  end if;

  -- Revalidate on every fetch: the owner must still be an enabled member who may view leave.
  if not exists (
    select 1
    from public.organization_users
    join public.profiles on profiles.user_id = organization_users.user_id
    where organization_users.organization_id = v_feed.organization_id
      and organization_users.user_id = v_feed.user_id
      and profiles.disabled_at is null
  ) or not public.agenda_user_has_org_permission(
    v_feed.organization_id,
    v_feed.user_id,
    'organization.time-off.view'
  ) then
    return null;
  end if;

  select organizations.name into v_organization_name
  from public.organizations
  where organizations.id = v_feed.organization_id;

  if v_feed.team_id is not null then
    select teams.name into v_team_name
    from public.teams
    where teams.id = v_feed.team_id and teams.organization_id = v_feed.organization_id;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'request_id', requests.id,
    'employee_name', trim(employees.first_name || ' ' || coalesce(employees.last_name, '')),
    'starts_on', requests.starts_on,
    'ends_on', requests.ends_on,
    'start_part', requests.start_part,
    'end_part', requests.end_part,
    'start_time', requests.start_time,
    'end_time', requests.end_time,
    'type_name', case when types.category = 'sick' then null else types.name end,
    'updated_at', coalesce(requests.decided_at, requests.created_at)
  ) order by requests.starts_on), '[]'::jsonb)
  into v_absences
  from public.time_off_requests as requests
  join public.employees on employees.id = requests.employee_id
  join public.time_off_types as types on types.id = requests.time_off_type_id
  where requests.organization_id = v_feed.organization_id
    and requests.status = 'approved'
    and requests.ends_on >= (now() at time zone 'utc')::date - 60
    and requests.starts_on <= (now() at time zone 'utc')::date + 400
    and (v_feed.team_id is null or employees.department_team_id = v_feed.team_id);

  return jsonb_build_object(
    'organization_name', v_organization_name,
    'team_name', v_team_name,
    'absences', v_absences
  );
end;

