declare
  v_uid uuid := (select auth.uid());
  v_today date := (now() at time zone 'utc')::date;
begin
  if v_uid is null or p_request.organization_id is null then
    return false;
  end if;

  if p_request.approver_permission is not null
    and public.has_org_permission(p_request.organization_id, p_request.approver_permission) then
    return true;
  end if;

  if p_request.escalated_at is not null
    and p_request.escalate_to_permission is not null
    and public.has_org_permission(p_request.organization_id, p_request.escalate_to_permission) then
    return true;
  end if;

  if v_uid = any(p_request.approver_user_ids) then
    return true;
  end if;

  if p_request.approver_employee_id is not null
    and p_request.approver_employee_id = public.current_employee_id(p_request.organization_id) then
    return true;
  end if;

  if p_request.employee_id is not null and public.is_employee_manager_of(p_request.employee_id) then
    return true;
  end if;

  -- Active delegation from any named approver to the signed-in user.
  return exists (
    select 1
    from public.approval_delegations delegation
    join public.employees delegator on delegator.id = delegation.employee_id
    join public.employees delegate on delegate.id = delegation.delegate_employee_id
    where delegation.organization_id = p_request.organization_id
      and delegate.user_id = v_uid
      and v_today between delegation.starts_on and delegation.ends_on
      and (
        delegator.user_id = any(p_request.approver_user_ids)
        or delegator.id = p_request.approver_employee_id
      )
  );
end;

