declare
  v_node public.file_nodes;
  v_parent public.file_nodes;
begin
  select * into v_node
  from public.file_nodes
  where id = p_node_id
  for update;

  if v_node.id is null or v_node.deleted_at is not null then
    raise exception 'File node not found' using errcode = 'P0002';
  end if;
  if not public.has_file_node_access(v_node.id, 'editor') then
    raise exception 'File node move is not allowed' using errcode = '42501';
  end if;
  if v_node.customer_id is not null and v_node.parent_id is null then
    raise exception 'Customer folders cannot be moved' using errcode = '42501';
  end if;
  if p_parent_id is null and exists (
    select 1
    from public.file_drives
    where id = v_node.drive_id
      and drive_type = 'customers'
  ) then
    raise exception 'Files cannot be moved to the customers drive root' using errcode = '42501';
  end if;
  if p_parent_id = p_node_id then
    raise exception 'A node cannot be moved into itself' using errcode = '23514';
  end if;

  if p_parent_id is not null then
    select * into v_parent
    from public.file_nodes
    where id = p_parent_id
    for update;
    if v_parent.id is null or v_parent.deleted_at is not null or v_parent.kind <> 'folder' then
      raise exception 'Destination folder not found' using errcode = '23514';
    end if;
    if v_parent.drive_id <> v_node.drive_id or not public.has_file_node_access(v_parent.id, 'editor') then
      raise exception 'Cross-drive or unauthorized moves are not allowed' using errcode = '42501';
    end if;
    if exists (
      with recursive descendants as (
        select id from public.file_nodes where parent_id = v_node.id
        union
        select child.id
        from public.file_nodes as child
        inner join descendants as parent on child.parent_id = parent.id
      )
      select 1 from descendants where id = p_parent_id
    ) then
      raise exception 'A folder cannot be moved into its descendant' using errcode = '23514';
    end if;
  end if;

  update public.file_nodes
  set parent_id = p_parent_id
  where id = v_node.id
  returning * into v_node;
  return v_node;
end;

