declare
  v_next bigint;
  v_period text := coalesce(p_period, '');
  v_permission text;
  v_max_existing bigint;
begin
  if p_organization_id is null then
    raise exception 'organization_id is required';
  end if;

  v_permission := case p_entity
    when 'task' then 'organization.tasks.create'
    when 'quote' then 'organization.quotes.create'
    when 'invoice' then 'organization.invoices.create'
    when 'purchase_order' then 'organization.purchase-orders.create'
    when 'order' then 'organization.orders.create'
    when 'shipment' then 'organization.orders.fulfill'
    else null
  end;

  if v_permission is null then
    raise exception 'unsupported number sequence entity';
  end if;

  if (select auth.role()) is distinct from 'service_role'
    and not coalesce(public.has_org_permission(p_organization_id, v_permission), false)
    and not (
      p_entity = 'shipment'
      and coalesce(
        public.has_org_permission(p_organization_id, 'organization.purchase-orders.receive'),
        false
      )
    )
  then
    raise insufficient_privilege using message = 'insufficient organization permission';
  end if;

  -- Serialize concurrent callers within the same (org, entity, period).
  perform pg_advisory_xact_lock(
    hashtext(p_organization_id::text || ':' || p_entity || ':' || v_period)
  );

  -- Rows inserted outside this function (seed data, imports, restores) can sit
  -- above the recorded counter. Realign against the highest existing number so
  -- we never hand out a value that would violate the unique number index.
  if p_entity = 'quote' then
    select max(quotes.number) into v_max_existing
    from public.quotes
    where quotes.organization_id = p_organization_id;
  elsif p_entity = 'task' then
    select max(tasks.number) into v_max_existing
    from public.tasks
    where tasks.organization_id = p_organization_id;
  elsif p_entity = 'invoice' then
    select max(invoices.number) into v_max_existing
    from public.invoices
    where invoices.organization_id = p_organization_id
      and (
        v_period = ''
        or (v_period ~ '^[0-9]+$' and invoices.number_year = v_period::integer)
      );
  elsif p_entity = 'purchase_order' then
    select max(purchase_orders.number) into v_max_existing
    from public.purchase_orders
    where purchase_orders.organization_id = p_organization_id;
  elsif p_entity = 'order' then
    select max(orders.number) into v_max_existing
    from public.orders
    where orders.organization_id = p_organization_id;
  elsif p_entity = 'shipment' then
    select max(shipments.number) into v_max_existing
    from public.shipments
    where shipments.organization_id = p_organization_id;
  end if;

  insert into public.organization_number_sequences (organization_id, entity, period, last_number)
  values (p_organization_id, p_entity, v_period, coalesce(v_max_existing, 0) + 1)
  on conflict (organization_id, entity, period) do update
    set last_number = greatest(
      public.organization_number_sequences.last_number,
      coalesce(v_max_existing, 0)
    ) + 1
  returning last_number into v_next;

  return v_next;
end;

