declare
  v_deleted integer;
  v_event_ids uuid[];
begin
  if p_batch_size < 1 or p_batch_size > 10000 then
    raise exception 'Audit retention batch size must be between 1 and 10000';
  end if;

  select array_agg(expired.id)
  into v_event_ids
  from (
    select event.id
    from public.audit_logs event
    left join public.organization_subscriptions subscription
      on subscription.organization_id = event.organization_id
    where event.occurred_at < p_now - make_interval(
      days => case
        when event.organization_id is null then 365
        when subscription.plan_key = 'enterprise'
          then coalesce(subscription.audit_log_retention_days, 365)
        when subscription.plan_key = 'business' then 90
        when subscription.plan_key = 'pro' then 7
        else 1
      end
    )
    order by event.occurred_at, event.id
    limit p_batch_size
  ) expired;

  if v_event_ids is null then
    return 0;
  end if;

  perform set_config('app.audit_retention', 'on', true);

  delete from public.audit_log_restricted_details
  where event_id = any(v_event_ids);

  delete from public.audit_logs
  where id = any(v_event_ids);

  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

