declare
  v_drive public.file_drives;
begin
  select * into v_drive
  from public.file_drives
  where id = p_drive_id
  for update;
  if v_drive.id is null or v_drive.drive_type not in ('personal', 'shared') then
    raise exception 'Owned file drive not found' using errcode = 'P0002';
  end if;
  if not public.has_org_permission(v_drive.organization_id, 'organization.files.update') then
    raise exception 'Drive reassignment is not allowed' using errcode = '42501';
  end if;
  if p_new_owner_user_id is not null and not exists (
    select 1
    from public.organization_users
    where organization_id = v_drive.organization_id
      and user_id = p_new_owner_user_id
  ) then
    raise exception 'New owner must be an organization user' using errcode = '23514';
  end if;

  update public.file_drives
  set
    owner_user_id = p_new_owner_user_id,
    lifecycle_state = case
      when p_new_owner_user_id is null then 'owner-missing'
      else 'active'
    end,
    archived_at = null,
    trashed_at = null,
    purge_after = null,
    owner_released_at = (now() at time zone 'utc')
  where id = v_drive.id
  returning * into v_drive;
  return v_drive;
end;

