declare
  v_shipment record;
  v_lines jsonb;
  v_result jsonb;
begin
  select shipments.id, shipments.direction, shipments.status, shipments.delivered_at,
    shipments.purchase_order_id, shipments.location_id
  into v_shipment
  from public.shipments
  where shipments.id = p_shipment_id
    and shipments.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'shipment not found' using errcode = 'P0002';
  end if;

  if v_shipment.direction <> 'inbound' then
    raise exception 'only inbound shipments are received' using errcode = '22023', hint = 'invalid_status';
  end if;

  if v_shipment.delivered_at is not null or v_shipment.status = 'cancelled' then
    raise exception 'this delivery was already received'
      using errcode = '22023', hint = 'shipment_already_shipped';
  end if;

  select jsonb_agg(jsonb_build_object(
    'lineId', shipment_lines.purchase_order_line_id,
    'quantity', shipment_lines.quantity,
    'lotNumber', shipment_lines.lot_number,
    'serialNumber', shipment_lines.serial_number,
    'expiresOn', shipment_lines.expires_on
  ) order by shipment_lines.position)
  into v_lines
  from public.shipment_lines
  where shipment_lines.shipment_id = p_shipment_id;

  v_result := public.receive_purchase_order(
    p_organization_id, v_shipment.purchase_order_id, coalesce(v_lines, '[]'::jsonb),
    coalesce(p_location_id, v_shipment.location_id), false, p_shipment_id
  );

  perform set_config('app.shipment_transition', 'on', true);
  update public.shipments
  set status = 'delivered', delivered_at = now(), status_occurred_at = now(),
    location_id = coalesce(p_location_id, location_id)
  where shipments.id = p_shipment_id;
  perform set_config('app.shipment_transition', 'off', true);

  return v_result || jsonb_build_object('purchaseOrderId', v_shipment.purchase_order_id);
end;

