CREATE OR REPLACE FUNCTION public.receive_purchase_order(p_organization_id uuid, p_purchase_order_id uuid, p_lines jsonb, p_location_id uuid DEFAULT NULL::uuid, p_allow_over_receipt boolean DEFAULT false, p_shipment_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order record;
  v_item jsonb;
  v_line record;
  v_quantity numeric(12, 3);
  v_location_id uuid;
  v_lot text;
  v_serial text;
  v_expires date;
  v_stock_id uuid;
  v_on_hand numeric(12, 3);
  v_allocated numeric(12, 3);
  v_variant_on_hand numeric(12, 3);
  v_average numeric(12, 4);
  v_unit_cost_base numeric(14, 4);
  v_received numeric(12, 3) := 0;
  v_status public.purchase_order_status;
  v_variant_ids uuid[] := '{}';
begin
  if not public.has_org_permission(p_organization_id, 'organization.purchase-orders.receive') then
    raise insufficient_privilege using message = 'purchase order receive permission required';
  end if;

  select purchase_orders.id, purchase_orders.status, purchase_orders.supplier_id,
    purchase_orders.exchange_rate, purchase_orders.ship_to_location_id, purchase_orders.number,
    purchase_orders.number_prefix
  into v_order
  from public.purchase_orders
  where purchase_orders.id = p_purchase_order_id
    and purchase_orders.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'purchase order not found' using errcode = 'P0002';
  end if;

  if v_order.status not in ('sent', 'partially_received', 'received') then
    raise exception 'only sent purchase orders can be received'
      using errcode = '22023', hint = 'purchase_order_not_sent';
  end if;

  if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'nothing to receive' using errcode = '22023', hint = 'purchase_order_nothing_to_receive';
  end if;

  for v_item in select * from jsonb_array_elements(p_lines)
  loop
    v_quantity := nullif(v_item ->> 'quantity', '')::numeric;
    continue when v_quantity is null or v_quantity <= 0;

    select purchase_order_lines.*
    into v_line
    from public.purchase_order_lines
    where purchase_order_lines.id = (v_item ->> 'lineId')::uuid
      and purchase_order_lines.purchase_order_id = p_purchase_order_id
    for update;

    if not found then
      raise exception 'purchase order line not found' using errcode = 'P0002';
    end if;

    if not p_allow_over_receipt
      and v_line.quantity_received + v_quantity
        > v_line.quantity_ordered - v_line.quantity_cancelled
    then
      raise exception 'received quantity exceeds the open quantity'
        using errcode = '22023', hint = 'purchase_order_over_receipt';
    end if;

    v_location_id := coalesce(
      nullif(v_item ->> 'locationId', '')::uuid,
      p_location_id,
      v_order.ship_to_location_id
    );
    v_lot := nullif(btrim(v_item ->> 'lotNumber'), '');
    v_serial := nullif(btrim(v_item ->> 'serialNumber'), '');
    v_expires := nullif(v_item ->> 'expiresOn', '')::date;
    v_unit_cost_base := round(v_line.unit_cost * v_order.exchange_rate, 4);

    perform public.lock_product_stock(p_organization_id, v_line.product_id);

    select coalesce(sum(inventory_stock_records.on_hand_quantity), 0)
    into v_variant_on_hand
    from public.inventory_stock_records
    where inventory_stock_records.variant_id = v_line.variant_id
      and inventory_stock_records.status = 'available';

    select inventory_stock_records.id
    into v_stock_id
    from public.inventory_stock_records
    where inventory_stock_records.organization_id = p_organization_id
      and inventory_stock_records.variant_id = v_line.variant_id
      and inventory_stock_records.location_id is not distinct from v_location_id
      and inventory_stock_records.lot_number is not distinct from v_lot
      and inventory_stock_records.serial_number is not distinct from v_serial
      and inventory_stock_records.expires_on is not distinct from v_expires
      and inventory_stock_records.status = 'available'
    order by inventory_stock_records.id
    limit 1;

    if v_stock_id is null then
      insert into public.inventory_stock_records (
        organization_id, product_id, variant_id, location_id, on_hand_quantity, status,
        lot_number, serial_number, expires_on, bin_location, unit_cost, created_by
      ) values (
        p_organization_id, v_line.product_id, v_line.variant_id, v_location_id, v_quantity,
        'available', v_lot, v_serial, v_expires, nullif(btrim(v_item ->> 'binLocation'), ''),
        round(v_unit_cost_base, 2), auth.uid()
      )
      returning id, on_hand_quantity, allocated_quantity
      into v_stock_id, v_on_hand, v_allocated;
    else
      update public.inventory_stock_records
      set on_hand_quantity = on_hand_quantity + v_quantity,
        unit_cost = round(v_unit_cost_base, 2),
        updated_by = auth.uid()
      where inventory_stock_records.id = v_stock_id
      returning on_hand_quantity, allocated_quantity
      into v_on_hand, v_allocated;
    end if;

    insert into public.inventory_movements (
      organization_id, stock_record_id, product_id, location_id, movement_type,
      on_hand_delta, allocated_delta, quantity_after, allocated_after, reason, created_by,
      supplier_id, purchase_order_id, shipment_id, reference_number
    ) values (
      p_organization_id, v_stock_id, v_line.product_id, v_location_id, 'purchase_receipt',
      v_quantity, 0, v_on_hand, least(v_allocated, v_on_hand), 'purchase order received',
      auth.uid(), v_order.supplier_id, p_purchase_order_id, p_shipment_id,
      v_order.number_prefix || v_order.number::text
    );

    select product_variants.average_cost into v_average
    from public.product_variants
    where product_variants.id = v_line.variant_id
    for update;

    update public.product_variants
    set average_cost = case
      when v_average is null or v_variant_on_hand <= 0 then v_unit_cost_base
      else round(
        (v_variant_on_hand * v_average + v_quantity * v_unit_cost_base)
          / (v_variant_on_hand + v_quantity),
        4
      )
    end
    where product_variants.id = v_line.variant_id;

    update public.purchase_order_lines
    set quantity_received = quantity_received + v_quantity
    where purchase_order_lines.id = v_line.id;

    v_received := v_received + v_quantity;
    v_variant_ids := array_append(v_variant_ids, v_line.variant_id);
  end loop;

  if v_received <= 0 then
    raise exception 'nothing to receive' using errcode = '22023', hint = 'purchase_order_nothing_to_receive';
  end if;

  v_status := public.refresh_purchase_order_status(p_purchase_order_id);

  return jsonb_build_object(
    'status', v_status,
    'received', v_received,
    'variantIds', to_jsonb(coalesce(
      (select array_agg(distinct variant_id) from unnest(v_variant_ids) as variant_id),
      '{}'::uuid[]
    ))
  );
end;
