declare
  v_shipment record;
  v_line record;
  v_location_id uuid;
  v_line_location_id uuid;
  v_source record;
  v_lot text;
  v_serial text;
  v_expires date;
  v_stock_id uuid;
  v_on_hand numeric(12, 3);
  v_allocated numeric(12, 3);
  v_status public.inventory_status;
  v_restocked numeric(12, 3) := 0;
  v_variant_ids uuid[] := '{}';
begin
  if not public.has_org_permission(p_organization_id, 'organization.orders.fulfill') then
    raise insufficient_privilege using message = 'order fulfill permission required';
  end if;

  select shipments.id, shipments.direction, shipments.status, shipments.delivered_at,
    shipments.order_id, shipments.location_id,
    orders.number_prefix || orders.number::text as order_reference
  into v_shipment
  from public.shipments
  join public.orders on orders.id = shipments.order_id
  where shipments.id = p_shipment_id
    and shipments.organization_id = p_organization_id
  for update of shipments;

  if not found then
    raise exception 'shipment not found' using errcode = 'P0002';
  end if;

  if v_shipment.direction <> 'return' then
    raise exception 'only returns are received here' using errcode = '22023', hint = 'invalid_status';
  end if;

  if v_shipment.delivered_at is not null or v_shipment.status = 'cancelled' then
    raise exception 'this return was already received'
      using errcode = '22023', hint = 'shipment_already_shipped';
  end if;

  v_location_id := coalesce(p_location_id, v_shipment.location_id);

  for v_line in
    select shipment_lines.product_id, shipment_lines.variant_id, shipment_lines.quantity,
      shipment_lines.lot_number, shipment_lines.serial_number, shipment_lines.expires_on,
      coalesce(shipment_lines.return_disposition, 'restock') as disposition,
      products.track_inventory, products.product_type, product_variants.average_cost
    from public.shipment_lines
    join public.products on products.id = shipment_lines.product_id
    left join public.product_variants on product_variants.id = shipment_lines.variant_id
    where shipment_lines.shipment_id = p_shipment_id
    order by shipment_lines.position, shipment_lines.id
  loop
    continue when v_line.disposition = 'write_off'
      or not (v_line.track_inventory and v_line.product_type = 'physical');

    v_status := case when v_line.disposition = 'restock' then 'available' else 'quarantined' end;
    select inventory_stock_records.location_id, inventory_stock_records.lot_number,
      inventory_stock_records.serial_number, inventory_stock_records.expires_on
    into v_source
    from public.inventory_movements
    join public.inventory_stock_records
      on inventory_stock_records.id = inventory_movements.stock_record_id
    where inventory_movements.order_id = v_shipment.order_id
      and inventory_movements.movement_type = 'sale'
      and inventory_stock_records.variant_id = v_line.variant_id
      and (v_line.lot_number is null or inventory_stock_records.lot_number = v_line.lot_number)
      and (v_line.serial_number is null or inventory_stock_records.serial_number = v_line.serial_number)
    order by inventory_movements.created_at desc
    limit 1;

    v_line_location_id := coalesce(v_location_id, v_source.location_id);
    v_lot := coalesce(v_line.lot_number, v_source.lot_number);
    v_serial := coalesce(v_line.serial_number, v_source.serial_number);
    v_expires := coalesce(v_line.expires_on, v_source.expires_on);
    perform public.lock_product_stock(p_organization_id, v_line.product_id);

    select inventory_stock_records.id
    into v_stock_id
    from public.inventory_stock_records
    where inventory_stock_records.organization_id = p_organization_id
      and inventory_stock_records.variant_id = v_line.variant_id
      and inventory_stock_records.location_id is not distinct from v_line_location_id
      and inventory_stock_records.lot_number is not distinct from v_lot
      and inventory_stock_records.serial_number is not distinct from v_serial
      and inventory_stock_records.expires_on is not distinct from v_expires
      and inventory_stock_records.status = v_status
    order by inventory_stock_records.id
    limit 1;

    if v_stock_id is null then
      insert into public.inventory_stock_records (
        organization_id, product_id, variant_id, location_id, on_hand_quantity, status,
        lot_number, serial_number, expires_on, unit_cost, created_by
      ) values (
        p_organization_id, v_line.product_id, v_line.variant_id, v_line_location_id,
        v_line.quantity, v_status, v_lot, v_serial, v_expires, round(v_line.average_cost, 2), auth.uid()
      )
      returning id, on_hand_quantity, allocated_quantity
      into v_stock_id, v_on_hand, v_allocated;
    else
      update public.inventory_stock_records
      set on_hand_quantity = on_hand_quantity + v_line.quantity, updated_by = auth.uid()
      where inventory_stock_records.id = v_stock_id
      returning on_hand_quantity, allocated_quantity
      into v_on_hand, v_allocated;
    end if;

    insert into public.inventory_movements (
      organization_id, stock_record_id, product_id, location_id, movement_type,
      on_hand_delta, allocated_delta, quantity_after, allocated_after, reason, created_by,
      order_id, shipment_id, reference_number
    ) values (
      p_organization_id, v_stock_id, v_line.product_id, v_line_location_id, 'return',
      v_line.quantity, 0, v_on_hand, v_allocated,
      case when v_status = 'available' then 'customer return restocked'
        else 'customer return quarantined' end,
      auth.uid(), v_shipment.order_id, p_shipment_id, v_shipment.order_reference
    );

    if v_status = 'available' then
      v_restocked := v_restocked + v_line.quantity;
      v_variant_ids := array_append(v_variant_ids, v_line.variant_id);
    end if;
  end loop;

  perform set_config('app.shipment_transition', 'on', true);
  update public.shipments
  set status = 'delivered', delivered_at = now(), status_occurred_at = now(),
    location_id = coalesce(v_location_id, v_line_location_id)
  where shipments.id = p_shipment_id;
  perform set_config('app.shipment_transition', 'off', true);

  return jsonb_build_object(
    'orderId', v_shipment.order_id,
    'restocked', v_restocked,
    'variantIds', to_jsonb(coalesce(
      (select array_agg(distinct variant_id) from unnest(v_variant_ids) as variant_id),
      '{}'::uuid[]
    ))
  );
end;

