declare
  v_invoice record;
  v_paid bigint;
  v_charges bigint;
  v_credited bigint;
  v_due bigint;
begin
  select id, kind, status, total_incl
  into v_invoice
  from public.invoices
  where id = p_invoice_id;

  if v_invoice.id is null then
    return;
  end if;

  select coalesce(sum(amount_cents), 0)
  into v_paid
  from public.invoice_payments
  where invoice_id = p_invoice_id
    and status = 'succeeded';

  select coalesce(sum(amount_cents), 0)
  into v_charges
  from public.invoice_charges
  where invoice_id = p_invoice_id;

  select coalesce(sum(round(abs(total_incl) * 100)), 0)
  into v_credited
  from public.invoices
  where original_invoice_id = p_invoice_id
    and kind = 'credit_note'
    and status in ('sent', 'paid', 'overdue');

  if v_invoice.kind = 'credit_note' or v_invoice.status in ('cancelled', 'paid') then
    v_due := 0;
  else
    v_due := greatest(
      0,
      round(v_invoice.total_incl * 100)::bigint + v_charges - v_credited - v_paid
    );
  end if;

  update public.invoices
  set amount_paid_cents = v_paid,
    amount_due_cents = v_due
  where id = p_invoice_id
    and (amount_paid_cents is distinct from v_paid or amount_due_cents is distinct from v_due);
end;

