  v_vat_inclusive boolean;
  v_vat_regime public.document_vat_regime;
  v_doc_discount_kind public.discount_kind;
  v_doc_discount_value numeric;
  v_subtotal numeric := 0;
  v_vat numeric := 0;
  v_total numeric := 0;
  v_line record;
  v_line_net numeric;
  v_line_discount numeric;
  v_line_after_discount numeric;
  v_line_excl numeric;
  v_new_subtotal numeric;
  v_ratio numeric;
  v_doc_discount_amount numeric := 0;
  v_updated_rows integer;
begin
  select discount_kind, discount_value, currency, vat_inclusive, vat_regime
  into v_doc_discount_kind, v_doc_discount_value, v_currency, v_vat_inclusive, v_vat_regime
  from public.invoices
  where id = p_invoice_id;

  if v_currency is null then
    raise exception 'invoice not found';
  end if;

  -- Mirror the client preview (apps/saas/lib/invoices/formatters.ts):
  -- vat_inclusive back-computes the net from the gross unit price, and a
  -- document-level discount scales VAT by the same ratio it scales the subtotal.
  for v_line in
    select quantity, unit_price, vat_rate, discount_kind, discount_value
    from public.invoice_lines
    where invoice_id = p_invoice_id
      and kind = 'line'
  loop
    -- Fixed-price rows have quantity forced to 1 by table check.
    v_line_net := v_line.quantity * v_line.unit_price;

    if v_line.discount_kind = 'percentage' then
      v_line_discount := v_line_net * (least(greatest(v_line.discount_value, 0), 100) / 100);
    elsif v_line.discount_kind = 'fixed' then
      v_line_discount := v_line.discount_value;
    else
      v_line_discount := 0;
    end if;

    v_line_after_discount :=
      case
        when v_line_net < 0 then v_line_net - v_line_discount
        else greatest(v_line_net - v_line_discount, 0)
      end;

    if v_vat_regime is distinct from 'standard' then
      v_line.vat_rate := 0;
    end if;

    if v_vat_inclusive then
      v_line_excl := v_line_after_discount / (1 + v_line.vat_rate / 100);
      v_subtotal := v_subtotal + v_line_excl;
      v_vat := v_vat + (v_line_after_discount - v_line_excl);
    else
      v_subtotal := v_subtotal + v_line_after_discount;
      v_vat := v_vat + v_line_after_discount * (v_line.vat_rate / 100);
