declare
  v_currency text;
  v_vat_inclusive boolean;
  v_vat_regime public.document_vat_regime;
  v_doc_discount_kind public.discount_kind;
  v_doc_discount_value numeric;
  v_subtotal numeric := 0;
  v_subtotal_before_doc_discount numeric := 0;
  v_vat numeric := 0;
  v_total numeric := 0;
  v_line record;
  v_line_net numeric;
  v_line_discount numeric;
  v_line_subtotal numeric;
  v_line_vat numeric;
  v_doc_discount_amount numeric := 0;
  v_selected_ids uuid[];
  v_updated_rows integer;
begin
  select discount_kind, discount_value, currency, vat_inclusive, vat_regime
  into v_doc_discount_kind, v_doc_discount_value, v_currency, v_vat_inclusive, v_vat_regime
  from public.quotes
  where id = p_quote_id;

  if v_currency is null then
    raise exception 'quote not found';
  end if;

  if p_selected_optional_line_ids is not null then
    select coalesce(array_agg((value)::uuid), '{}'::uuid[])
    into v_selected_ids
    from jsonb_array_elements_text(p_selected_optional_line_ids);
  end if;

  for v_line in
    select id, kind, quantity, unit_price, vat_rate,
           discount_kind, discount_value, is_optional,
           pricing_mode, subscription_periods
    from public.quote_lines
    where quote_id = p_quote_id
      and kind = 'line'
  loop
    if v_line.is_optional
       and (v_selected_ids is null or not (v_line.id = any (v_selected_ids))) then
      continue;
    end if;

    -- Per-period net; subscription rows multiply by the contracted periods
    -- count (null = open-ended → treat as a single period for cached totals).
    -- Fixed-price rows have quantity forced to 1 by table check.
    v_line_net := v_line.quantity * v_line.unit_price;
    if v_line.pricing_mode = 'subscription' then
      v_line_net := v_line_net * coalesce(v_line.subscription_periods, 1);
    end if;

    if v_line.discount_kind = 'percentage' then
      v_line_discount := v_line_net * (v_line.discount_value / 100);
    elsif v_line.discount_kind = 'fixed' then
      v_line_discount := v_line.discount_value;
    else
      v_line_discount := 0;
    end if;

    v_line_subtotal := greatest(v_line_net - v_line_discount, 0);

    if v_vat_regime is distinct from 'standard' then
      v_line.vat_rate := 0;
    end if;

    -- vat_inclusive quotes store gross unit prices, so the net amount and VAT
    -- are extracted from the discounted line amount instead of added on top.
    if coalesce(v_vat_inclusive, false) then
      v_line_vat := v_line_subtotal - (v_line_subtotal / (1 + v_line.vat_rate / 100));
      v_line_subtotal := v_line_subtotal - v_line_vat;
    else
      v_line_vat := v_line_subtotal * (v_line.vat_rate / 100);
    end if;

    v_subtotal := v_subtotal + v_line_subtotal;
    v_vat := v_vat + v_line_vat;
  end loop;

  v_subtotal_before_doc_discount := v_subtotal;

  if v_doc_discount_kind = 'percentage' then
    v_doc_discount_amount := v_subtotal_before_doc_discount
      * (least(greatest(v_doc_discount_value, 0), 100) / 100);
  elsif v_doc_discount_kind = 'fixed' then
    v_doc_discount_amount := least(
      greatest(v_doc_discount_value, 0),
      v_subtotal_before_doc_discount
    );
  end if;

  v_subtotal := greatest(v_subtotal_before_doc_discount - v_doc_discount_amount, 0);

  -- A document discount lowers the taxable base, so VAT shrinks with it.
  -- Scaling the summed VAT distributes the discount pro rata across lines and
  -- keeps mixed VAT rates correct.
  if v_doc_discount_amount > 0 then
    if v_subtotal_before_doc_discount > 0 then
      v_vat := v_vat * (v_subtotal / v_subtotal_before_doc_discount);
    else
      v_vat := 0;
    end if;
  end if;

  v_subtotal := round(v_subtotal, 2);
  v_vat := round(v_vat, 2);
  v_total := v_subtotal + v_vat;

  update public.quotes
  set subtotal_excl = v_subtotal,
      vat_total = v_vat,
      total_incl = v_total
  where id = p_quote_id;

  get diagnostics v_updated_rows = row_count;
  if v_updated_rows <> 1 then
    raise insufficient_privilege using message = 'insufficient quote update permission';
  end if;
end;

