declare
  v_order record;
  v_open_shipping numeric;
  v_open_invoicing numeric;
begin
  if auth.uid() is not null
    and not public.has_org_permission(p_organization_id, 'organization.orders.view')
  then
    raise insufficient_privilege using message = 'order view permission required';
  end if;

  select orders.status, orders.invoicing_policy
  into v_order
  from public.orders
  where orders.id = p_order_id
    and orders.organization_id = p_organization_id;

  if v_order.status is distinct from 'confirmed' then
    return v_order.status;
  end if;

  select
    coalesce(sum(
      case when order_lines.line_type = 'product' and (
          products.product_type = 'physical'
          or products.digital_delivery in ('file', 'license_key')
        )
        then greatest(order_lines.quantity - order_lines.quantity_cancelled - progress.fulfilled, 0)
        else 0 end
    ), 0),
    coalesce(sum(
      greatest(order_lines.quantity - order_lines.quantity_cancelled - progress.invoiced, 0)
    ), 0)
  into v_open_shipping, v_open_invoicing
  from public.order_lines
  left join public.products on products.id = order_lines.product_id
  join public.order_line_progress(p_organization_id, p_order_id) as progress
    on progress.order_line_id = order_lines.id
  where order_lines.order_id = p_order_id;

  if v_open_shipping > 0
    or (v_order.invoicing_policy <> 'manual' and v_open_invoicing > 0)
  then
    return v_order.status;
  end if;

  update public.orders
  set status = 'completed', completed_at = now()
  where orders.id = p_order_id;

  return 'completed';
end;

