declare
  v_status public.purchase_order_status;
  v_open numeric;
  v_received numeric;
begin
  select purchase_orders.status into v_status
  from public.purchase_orders
  where purchase_orders.id = p_purchase_order_id;

  if v_status not in ('sent', 'partially_received', 'received') then
    return v_status;
  end if;

  select
    coalesce(sum(greatest(quantity_ordered - quantity_received - quantity_cancelled, 0)), 0),
    coalesce(sum(quantity_received), 0)
  into v_open, v_received
  from public.purchase_order_lines
  where purchase_order_lines.purchase_order_id = p_purchase_order_id;

  v_status := case
    when v_open <= 0 then 'received'
    when v_received > 0 then 'partially_received'
    else 'sent'
  end;

  update public.purchase_orders
  set
    status = v_status,
    received_at = case when v_status = 'received' then coalesce(received_at, now()) else null end
  where purchase_orders.id = p_purchase_order_id;

  return v_status;
end;

