declare
  v_org_id uuid;
  v_quote_id uuid;
  v_status public.quote_status;
  v_version_id uuid;
  v_name text := nullif(trim(p_payload->>'name'), '');
  v_email text := nullif(trim(p_payload->>'email'), '');
  v_reason text := nullif(trim(p_payload->>'reason'), '');
begin
  if p_org_slug is null or p_quote_id is null then
    raise exception 'quote not found';
  end if;
  if v_name is null or v_email is null then
    raise exception 'name and email are required';
  end if;
  if v_reason is null then
    raise exception 'reason is required';
  end if;

  select o.id into v_org_id
  from public.organizations o
  where lower(o.slug) = lower(p_org_slug)
  limit 1;

  if v_org_id is null then
    raise exception 'quote not found';
  end if;

  select q.id, q.status
  into v_quote_id, v_status
  from public.quotes q
  where q.id = p_quote_id
    and q.organization_id = v_org_id
    and q.archived_at is null
  for update;

  if v_quote_id is null then
    raise exception 'quote not found';
  end if;

  if v_status not in ('sent', 'expired', 'changes_requested') then
    raise exception 'quote is not in sent state';
  end if;

  select qv.id into v_version_id
  from public.quote_versions qv
  where qv.quote_id = v_quote_id
  order by qv.version desc
  limit 1;

  update public.quotes
  set status = 'rejected',
      rejected_at = now() at time zone 'utc',
      accepted_by_name = v_name,
      accepted_by_email = v_email,
      accepted_ip = p_ip,
      accepted_user_agent = p_user_agent
  where id = v_quote_id;

  if v_version_id is not null then
    update public.quote_versions
    set status = 'rejected',
        reason = v_reason
    where id = v_version_id;
  end if;

  insert into public.quote_status_history
    (quote_id, organization_id, from_status, to_status,
     actor_customer_name, actor_customer_email, reason, ip, user_agent)
  values
    (v_quote_id, v_org_id, v_status, 'rejected',
     v_name, v_email, v_reason, p_ip, p_user_agent);

  return v_quote_id;
end;

