    organization_id,
    agenda_item_id,
    user_id,
    email,
    display_name,
    role,
    participation_status,
    is_optional,
    is_organizer,
    customer_id,
    customer_contact_id
  )
  select distinct on (
    coalesce(
      case
        when attendee.customer_contact_id is not null
          then 'contact:' || attendee.customer_contact_id::text
      end,
      case
        when attendee.customer_id is not null then 'customer:' || attendee.customer_id::text
      end,
      attendee.user_id::text,
      'email:' || lower(attendee.email)
    )
