  ) then
    raise exception 'invoice not found in organization' using errcode = '23503';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'invoice lines must be an array' using errcode = '22023';
