  if p_replace_lines and exists (
    select 1
    from jsonb_to_recordset(coalesce(p_lines, '[]'::jsonb))
      as line(product_id uuid, task_id uuid)
    where (
      line.product_id is not null
      and not exists (
        select 1 from public.products
        where id = line.product_id and organization_id = p_organization_id
      )
    ) or (
      line.task_id is not null
      and not exists (
        select 1 from public.tasks
        where id = line.task_id and organization_id = p_organization_id
      )
    )
  ) then
    raise exception 'invoice line reference not found in organization' using errcode = '23503';
  end if;

  if p_replace_tasks and exists (
    select 1
    from unnest(coalesce(p_task_ids, '{}'::uuid[])) as requested(task_id)
    where not exists (
      select 1 from public.tasks
      where id = requested.task_id and organization_id = p_organization_id
    )
  ) then
    raise exception 'invoice task not found in organization' using errcode = '23503';
  end if;

  if p_replace_lines then
    -- Order, shipment, and promotion links survive an editor save that sends
    -- the existing line id without them.
    select coalesce(jsonb_object_agg(
      invoice_lines.id::text,
      jsonb_build_object(
        'order_line_id', invoice_lines.order_line_id,
        'shipment_id', invoice_lines.shipment_id,
        'promotion_id', invoice_lines.promotion_id
      )
    ), '{}'::jsonb)
    into v_links
    from public.invoice_lines
    where invoice_lines.organization_id = p_organization_id
      and invoice_lines.invoice_id = p_invoice_id
      and (
        invoice_lines.order_line_id is not null
        or invoice_lines.shipment_id is not null
        or invoice_lines.promotion_id is not null
      );

    delete from public.invoice_lines
    where organization_id = p_organization_id and invoice_id = p_invoice_id;

    insert into public.invoice_lines (
      organization_id, invoice_id, kind, line_type, product_id, task_id,
      title, description, quantity, unit, unit_price, vat_rate,
      discount_kind, discount_value, pricing_mode, position, stock_mode, variant_id,
      order_line_id, shipment_id, promotion_id
    )
    select
      p_organization_id, p_invoice_id, line.kind, line.line_type,
      line.product_id, line.task_id, line.title, line.description,
      line.quantity, line.unit, line.unit_price, line.vat_rate,
      line.discount_kind, line.discount_value, line.pricing_mode, line.position,
      coalesce(line.stock_mode, 'auto'), line.variant_id,
      coalesce(line.order_line_id, (v_links -> line.id::text ->> 'order_line_id')::uuid),
      coalesce(line.shipment_id, (v_links -> line.id::text ->> 'shipment_id')::uuid),
      coalesce(line.promotion_id, (v_links -> line.id::text ->> 'promotion_id')::uuid)
    from jsonb_to_recordset(coalesce(p_lines, '[]'::jsonb)) as line(
      id uuid,
      order_line_id uuid,
      shipment_id uuid,
      promotion_id uuid,
      kind public.invoice_line_kind,
      line_type public.invoice_line_type,
      product_id uuid,
      variant_id uuid,
      task_id uuid,
      title text,
      description text,
      quantity numeric,
      unit text,
      unit_price numeric,
      vat_rate numeric,
      discount_kind public.discount_kind,
      discount_value numeric,
      pricing_mode public.invoice_line_pricing_mode,
      position numeric,
      stock_mode public.document_line_stock_mode
    );
  end if;

  if p_replace_tasks then
    delete from public.invoice_tasks
    where organization_id = p_organization_id and invoice_id = p_invoice_id;

    insert into public.invoice_tasks (organization_id, invoice_id, task_id, position)
    select p_organization_id, p_invoice_id, requested.task_id, requested.position - 1
    from (
      select task_id, min(position) as position
      from unnest(coalesce(p_task_ids, '{}'::uuid[])) with ordinality
        as input(task_id, position)
      group by task_id
    ) as requested
    order by requested.position;
  end if;
end;

