declare
  v_default numeric(5, 2);
begin
  if not exists (
    select 1
    from public.organizations
    where organizations.id = p_organization_id
  ) then
    raise exception 'organization not found' using errcode = 'P0001';
  end if;

  if jsonb_typeof(p_rates) is distinct from 'array' or jsonb_array_length(p_rates) < 1 then
    raise exception 'vat rates must be a non-empty array' using errcode = '22023';
  end if;

  if (
    select count(*)
    from jsonb_array_elements(p_rates) as rate
    where coalesce((rate ->> 'isDefault')::boolean, false)
  ) is distinct from 1 then
    raise exception 'exactly one vat rate must be default' using errcode = '22023';
  end if;

  delete from public.organization_vat_rates
  where organization_vat_rates.organization_id = p_organization_id;

  insert into public.organization_vat_rates (
    id,
    organization_id,
    rate,
    is_default,
    position
  )
  select
    coalesce((rate ->> 'id')::uuid, gen_random_uuid()),
    p_organization_id,
    (rate ->> 'rate')::numeric,
    coalesce((rate ->> 'isDefault')::boolean, false),
    coalesce((rate ->> 'position')::integer, 0)
  from jsonb_array_elements(p_rates) as rate;

  select organization_vat_rates.rate
  into v_default
  from public.organization_vat_rates
  where organization_vat_rates.organization_id = p_organization_id
    and organization_vat_rates.is_default
  limit 1;

  update public.organizations
  set default_vat_rate = v_default
  where organizations.id = p_organization_id;
end;

