declare
  v_actor_is_platform_admin boolean := false;
  v_organization_id uuid;
  v_role_scope text;
  v_uid uuid := (select auth.uid());
begin
  select roles.scope::text, roles.organization_id
  into v_role_scope, v_organization_id
  from public.roles
  where roles.id = p_role_id;

  if not found then
    raise exception 'role not found' using errcode = '23503';
  end if;

  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select public.authorize_scope('system', null, 'system.roles.manage')
  into v_actor_is_platform_admin;

  if not v_actor_is_platform_admin
    and not (
      v_role_scope in ('organization', 'user', 'team')
      and public.authorize_scope(
        'organization',
        v_organization_id,
        'organization.roles.update'
      )
      and public.authorize_scope(
        'organization',
        v_organization_id,
        'organization.roles.create'
      )
    )
  then
    raise exception 'not authorized to replace role permissions';
  end if;

  if exists (
    select 1
    from unnest(coalesce(p_permission_ids, '{}'::uuid[])) as requested(permission_id)
    where not exists (
      select 1 from public.permissions where id = requested.permission_id
    )
  ) then
    raise exception 'permission not found' using errcode = '23503';
  end if;

  delete from public.role_permissions where role_id = p_role_id;

  insert into public.role_permissions (role_id, permission_id)
  select p_role_id, requested.permission_id
  from (
    select distinct permission_id
    from unnest(coalesce(p_permission_ids, '{}'::uuid[])) as input(permission_id)
  ) as requested;

  insert into public.audit_logs (
    organization_id,
    organization_name_snapshot,
    scope,
    actor_kind,
    actor_id,
    actor_is_platform_admin,
    event_type,
    category,
    outcome,
    source,
    target_type,
    target_id,
    safe_metadata
  )
  values (
    v_organization_id,
    (
      select organizations.name
      from public.organizations
      where organizations.id = v_organization_id
    ),
    case when v_organization_id is null then 'platform' else 'organization' end,
    case when v_actor_is_platform_admin then 'platform_admin' else 'user' end,
    v_uid,
    v_actor_is_platform_admin,
    'rbac.mutation.completed',
    'permissions',
    'success',
    'database',
    'role',
    p_role_id::text,
    jsonb_build_object('operation', 'replace-role-permissions')
  );
end;

