declare
  v_org_id uuid;
  v_quote_id uuid;
  v_status public.quote_status;
  v_version integer;
  v_version_id uuid;
  v_valid_until date;
  v_name text := nullif(trim(p_payload->>'name'), '');
  v_email text := nullif(trim(p_payload->>'email'), '');
  v_comment text := nullif(trim(p_payload->>'comment'), '');
begin
  if p_org_slug is null or p_quote_id is null then
    raise exception 'quote not found';
  end if;
  if v_name is null or v_email is null then
    raise exception 'name and email are required';
  end if;
  if v_comment is null then
    raise exception 'comment is required';
  end if;

  select o.id into v_org_id
  from public.organizations o
  where lower(o.slug) = lower(p_org_slug)
  limit 1;

  if v_org_id is null then
    raise exception 'quote not found';
  end if;

  select q.id, q.status
  into v_quote_id, v_status
  from public.quotes q
  where q.id = p_quote_id
    and q.organization_id = v_org_id
    and q.archived_at is null
  for update;

  if v_quote_id is null then
    raise exception 'quote not found';
  end if;

  if v_status <> 'sent' then
    raise exception 'quote is not in sent state';
  end if;

  select qv.id, qv.version, qv.valid_until
  into v_version_id, v_version, v_valid_until
  from public.quote_versions qv
  where qv.quote_id = v_quote_id
  order by qv.version desc
  limit 1;

  if v_version_id is null then
    raise exception 'quote is not in sent state';
  end if;

  if v_valid_until is not null and v_valid_until < (now() at time zone 'utc')::date then
    raise exception 'quote has expired';
  end if;

  update public.quotes
  set status = 'changes_requested',
      changes_requested_at = now() at time zone 'utc'
  where id = v_quote_id;

