declare
  v_existing public.file_upload_reservations;
  v_result public.file_upload_reservations;
  v_quota bigint;
  v_stored bigint;
  v_reserved bigint;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_expected_bytes < 0 or p_expires_at <= (now() at time zone 'utc') then
    raise exception 'Invalid upload reservation' using errcode = '23514';
  end if;
  if not public.can_create_file_child(p_organization_id, p_drive_id, p_parent_id) then
    raise exception 'Upload reservation is not allowed' using errcode = '42501';
  end if;

  select * into v_existing
  from public.file_upload_reservations
  where organization_id = p_organization_id
    and created_by = (select auth.uid())
    and idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    return v_existing;
  end if;

  insert into public.file_storage_settings (organization_id)
  values (p_organization_id)
  on conflict (organization_id) do nothing;
  perform 1
  from public.file_storage_settings
  where organization_id = p_organization_id
  for update;
  v_quota := public.get_file_storage_quota_bytes(p_organization_id);
  select coalesce(sum(byte_size), 0) into v_stored
  from public.file_versions
  where organization_id = p_organization_id;
  select coalesce(sum(expected_bytes), 0) into v_reserved
  from public.file_upload_reservations
  where organization_id = p_organization_id
    and status in ('reserved', 'uploaded')
    and expires_at > (now() at time zone 'utc');
  if v_quota is not null and v_stored + v_reserved + p_expected_bytes > v_quota then
    raise exception 'File storage quota exceeded' using errcode = 'P0001';
  end if;

  insert into public.file_upload_reservations (
    organization_id, drive_id, node_id, parent_id, idempotency_key, file_name,
    media_type, expected_bytes, storage_bucket, storage_path, expires_at, created_by
  ) values (
    p_organization_id, p_drive_id, p_node_id, p_parent_id, p_idempotency_key,
    p_file_name, p_media_type, p_expected_bytes, p_storage_bucket, p_storage_path,
    p_expires_at, (select auth.uid())
  )
  returning * into v_result;
  return v_result;
end;

