declare
  v_count integer;
begin
  if not public.has_org_permission(p_organization_id, 'organization.general.view') then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  update public.notification_recipients as recipient
  set
    resolved_at = coalesce(recipient.resolved_at, (now() at time zone 'utc')),
    read_at = coalesce(recipient.read_at, (now() at time zone 'utc'))
  from public.notification_events as event
  where event.id = recipient.event_id
    and event.organization_id = p_organization_id
    and event.type = p_type
    and event.subject_type = p_subject_type
    and event.subject_id = p_subject_id
    and recipient.organization_id = p_organization_id
    and recipient.dismissed_at is null
    and recipient.resolved_at is null;

  get diagnostics v_count = row_count;
  return v_count;
end;

declare
  v_node public.file_nodes;
  v_count integer;
begin
  select * into v_node from public.file_nodes where id = p_node_id for update;
  if v_node.id is null or v_node.deleted_at is null then
    raise exception 'Trashed file node not found' using errcode = 'P0002';
  end if;
  if not public.has_file_node_access(v_node.id, 'editor') then
    raise exception 'File node restore is not allowed' using errcode = '42501';
  end if;
  if v_node.parent_id is not null and exists (
    select 1
    from public.file_nodes as parent
    where parent.id = v_node.parent_id
      and parent.deleted_at is not null
      and parent.deletion_batch_id <> v_node.deletion_batch_id
  ) then
    raise exception 'Restore the parent folder first' using errcode = '23514';
  end if;

  update public.file_nodes
  set deleted_at = null, deletion_batch_id = null, deleted_by = null, purge_after = null
  where deletion_batch_id = v_node.deletion_batch_id;
  get diagnostics v_count = row_count;
  return v_count;
end;

