  v_moved numeric(12, 3);
begin
  if auth.uid() is not null and not public.has_org_permission(
    p_organization_id,
    'organization.invoices.update'
  ) then
    raise insufficient_privilege using message = 'invoice update permission required';
  end if;

  if p_credit_note_id is null then
    for v_line in
      select invoice_lines.id
      from public.invoice_lines
      where invoice_lines.invoice_id = p_invoice_id
        and invoice_lines.organization_id = p_organization_id
    loop
      v_returned := v_returned + public.return_consumed_allocations(
        p_organization_id,
        v_line.id,
        null,
        'invoice stock returned',
        p_invoice_id,
        auth.uid()
      );
    end loop;

    return v_returned;
  end if;

  select invoices.original_invoice_id
  into v_original_id
  from public.invoices
  where invoices.id = p_credit_note_id
    and invoices.organization_id = p_organization_id
    and invoices.kind = 'credit_note'
    and invoices.original_invoice_id = p_invoice_id;

  if v_original_id is null then
    raise exception 'credit note not found for invoice' using errcode = '23503';
  end if;

  for v_line in
    select invoice_lines.product_id, invoice_lines.quantity
    from public.invoice_lines
    where invoice_lines.invoice_id = p_credit_note_id
      and invoice_lines.organization_id = p_organization_id
      and invoice_lines.kind = 'line'
      and invoice_lines.line_type = 'product'
      and invoice_lines.product_id is not null
      and invoice_lines.quantity > 0
    order by invoice_lines.position, invoice_lines.id
  loop
    v_left := v_line.quantity;

    for v_source in
      select invoice_lines.id
      from public.invoice_lines
      where invoice_lines.invoice_id = p_invoice_id
        and invoice_lines.organization_id = p_organization_id
        and invoice_lines.product_id = v_line.product_id
      order by invoice_lines.position, invoice_lines.id
    loop
      exit when v_left <= 0;
