declare
  v_target public.workflow_definitions;
begin
  if auth.role() is distinct from 'service_role'
    and not public.authorize_scope('system', null, 'system.workflows.manage') then
    raise exception 'not allowed to change the default lifecycle' using errcode = '42501';
  end if;

  select * into v_target
  from public.workflow_definitions
  where id = p_definition_id
  for update;

  if not found then
    raise exception 'workflow definition not found' using errcode = 'P0002';
  end if;
  if v_target.owner_scope <> 'system'
    or v_target.purpose <> 'lifecycle'
    or v_target.status <> 'published' then
    raise exception 'only a published system lifecycle can be the default' using errcode = '23514';
  end if;

  update public.workflow_definitions
  set is_default = false
  where subject_type = v_target.subject_type
    and is_default
    and id <> v_target.id;

  update public.workflow_definitions
  set is_default = true
  where id = v_target.id
  returning * into v_target;

  return v_target;
end;

