declare
  v_product public.products;
  v_option jsonb;
  v_option_id uuid;
  v_option_ids uuid[] := '{}';
  v_value text;
  v_value_position integer;
  v_combination uuid[];
  v_variant_id uuid;
  v_default_id uuid;
  v_kept uuid[] := '{}';
  v_position integer := 0;
  v_option_position integer := 0;
begin
  select * into v_product from public.products where id = p_product_id for update;
  if not found then
    raise exception 'product not found' using errcode = 'P0002';
  end if;
  if jsonb_typeof(coalesce(p_options, '[]'::jsonb)) <> 'array' then
    raise exception 'options must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(coalesce(p_options, '[]'::jsonb)) > 3 then
    raise exception 'a product can have at most 3 options' using errcode = '23514';
  end if;

  -- Upsert options by name and values by text, then drop what is gone.
  for v_option in select * from jsonb_array_elements(coalesce(p_options, '[]'::jsonb)) loop
    select o.id into v_option_id
    from public.product_options o
    where o.product_id = p_product_id and lower(o.name) = lower(btrim(v_option ->> 'name'));

    if v_option_id is null then
      insert into public.product_options (organization_id, product_id, name, position)
      values (v_product.organization_id, p_product_id, btrim(v_option ->> 'name'), v_option_position)
      returning id into v_option_id;
    else
      update public.product_options
      set name = btrim(v_option ->> 'name'), position = v_option_position, updated_at = now()
      where id = v_option_id;
    end if;

    v_value_position := 0;
    for v_value in select btrim(value) from jsonb_array_elements_text(v_option -> 'values') loop
      insert into public.product_option_values (organization_id, option_id, value, position)
      values (v_product.organization_id, v_option_id, v_value, v_value_position)
      on conflict (option_id, lower(value)) do update set position = excluded.position, value = excluded.value;
      v_value_position := v_value_position + 1;
    end loop;

    delete from public.product_option_values pov
    where pov.option_id = v_option_id
      and lower(pov.value) not in (
        select lower(btrim(value)) from jsonb_array_elements_text(v_option -> 'values')
      );

    v_option_ids := v_option_ids || v_option_id;
    v_option_position := v_option_position + 1;
    v_option_id := null;
  end loop;

  delete from public.product_options o
  where o.product_id = p_product_id and not (o.id = any (v_option_ids));

  v_default_id := public.product_default_variant_id(p_product_id);

  if cardinality(v_option_ids) = 0 then
    -- No options: the default variant is the only sellable unit.
    update public.product_variants set title = '', position = 0 where id = v_default_id;
    v_kept := array[v_default_id];
  else
    -- Walk every option-value combination in option order.
    for v_combination in
      with recursive combos(depth, ids, positions) as (
        select 0, '{}'::uuid[], '{}'::integer[]
        union all
        select c.depth + 1, c.ids || pov.id, c.positions || pov.position
        from combos c
        join public.product_option_values pov on pov.option_id = v_option_ids[c.depth + 1]
        where c.depth < cardinality(v_option_ids)
      )
      select ids from combos where depth = cardinality(v_option_ids) order by positions
    loop
      if v_position >= 100 then
        raise exception 'a product can have at most 100 variants' using errcode = '23514';
      end if;

      select v.id into v_variant_id
      from public.product_variants v
      where v.product_id = p_product_id
        and (
          select coalesce(array_agg(l.option_value_id order by l.option_value_id), '{}')
          from public.product_variant_option_values l
          where l.variant_id = v.id
        ) = (select array_agg(x order by x) from unnest(v_combination) x);

      -- Adding an option: the first combination that extends an existing
      -- variant adopts it, so its stock and lines carry over.
      if v_variant_id is null then
        select v.id into v_variant_id
        from public.product_variants v
        where v.product_id = p_product_id
          and not (v.id = any (v_kept))
          and exists (select 1 from public.product_variant_option_values l where l.variant_id = v.id)
          and (
            select array_agg(l.option_value_id)
            from public.product_variant_option_values l
            where l.variant_id = v.id
          ) <@ v_combination
        order by v.is_default desc, v.position
        limit 1;
      end if;

      -- The first combination adopts the default variant when it has no
      -- values yet, so existing stock and lines stay on it.
      if v_variant_id is null and v_position = 0 and not exists (
        select 1 from public.product_variant_option_values l where l.variant_id = v_default_id
      ) then
        v_variant_id := v_default_id;
      end if;

      if v_variant_id is null then
        insert into public.product_variants (organization_id, product_id, status, position)
        values (v_product.organization_id, p_product_id, 'active', v_position)
        returning id into v_variant_id;
      end if;

      delete from public.product_variant_option_values where variant_id = v_variant_id;
      insert into public.product_variant_option_values (variant_id, option_value_id, organization_id)
      select v_variant_id, unnest(v_combination), v_product.organization_id;

      update public.product_variants v
      set position = v_position,
          status = case when v.status = 'archived' then 'active' else v.status end,
          title = (
            select string_agg(pov.value, ' / ' order by po.position)
            from unnest(v_combination) as c(id)
            join public.product_option_values pov on pov.id = c.id
            join public.product_options po on po.id = pov.option_id
          ),
          updated_at = now()
      where v.id = v_variant_id;

      v_kept := v_kept || v_variant_id;
      v_position := v_position + 1;
      v_variant_id := null;
    end loop;

    -- The default must be a live combination.
    if not (v_default_id = any (v_kept)) then
      update public.product_variants set is_default = false where id = v_default_id;
      update public.product_variants set is_default = true where id = v_kept[1];
    end if;
  end if;

  -- Variants outside the matrix: delete when unused, archive otherwise.
  update public.product_variants v
  set status = 'archived', is_default = false, updated_at = now()
  where v.product_id = p_product_id
    and not (v.id = any (v_kept))
    and (
      exists (select 1 from public.inventory_stock_records r where r.variant_id = v.id)
      or exists (select 1 from public.inventory_movements m where m.variant_id = v.id)
      or exists (select 1 from public.inventory_allocations a where a.variant_id = v.id)
      or exists (select 1 from public.task_materials t where t.variant_id = v.id)
      or exists (select 1 from public.customer_assets c where c.variant_id = v.id)
      or exists (select 1 from public.quote_lines q where q.variant_id = v.id)
      or exists (select 1 from public.quote_version_lines q where q.variant_id = v.id)
      or exists (select 1 from public.invoice_lines i where i.variant_id = v.id)
    );

  delete from public.product_variants v
  where v.product_id = p_product_id
    and not (v.id = any (v_kept))
    and v.status <> 'archived';
end;

