declare
  v_user_id uuid := auth.uid();
  v_current_status public.task_status;
begin
  if v_user_id is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;

  if not public.has_org_permission(
    p_organization_id,
    'organization.tasks.update'
  ) then
    raise insufficient_privilege using message = 'task update permission required';
  end if;

  select tasks.status
  into v_current_status
  from public.tasks
  where tasks.id = p_task_id
    and tasks.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'task not found in organization' using errcode = '23503';
  end if;

  if v_current_status <> p_status
    and (v_current_status = 'done' or p_status = 'done')
  then
    perform public.apply_task_material_consumption(
      p_organization_id,
      p_task_id,
      p_status = 'done'
    );
  end if;

  update public.tasks
  set
    status = p_status,
    position = coalesce(p_position, tasks.position),
    updated_by = v_user_id
  where tasks.id = p_task_id
    and tasks.organization_id = p_organization_id;
end;

