declare
  v_shipment record;
  v_line record;
  v_allocation record;
  v_stock record;
  v_status public.shipment_status;
  v_remaining numeric(12, 3);
  v_take numeric(12, 3);
  v_on_hand numeric(12, 3);
  v_reserved numeric(12, 3);
begin
  if not public.has_org_permission(p_organization_id, 'organization.orders.fulfill') then
    raise insufficient_privilege using message = 'order fulfill permission required';
  end if;

  select shipments.*, orders.status as order_status,
    orders.number_prefix || orders.number::text as order_reference
  into v_shipment
  from public.shipments
  join public.orders on orders.id = shipments.order_id
  where shipments.id = p_shipment_id
    and shipments.organization_id = p_organization_id
  for update of shipments;

  if not found then
    raise exception 'shipment not found' using errcode = 'P0002';
  end if;

  if v_shipment.direction <> 'outbound' then
    raise exception 'only outbound shipments ship' using errcode = '22023', hint = 'invalid_status';
  end if;

  if v_shipment.shipped_at is not null or v_shipment.status = 'cancelled' then
    raise exception 'this shipment already left'
      using errcode = '22023', hint = 'shipment_already_shipped';
  end if;

  if v_shipment.order_status <> 'confirmed' then
    raise exception 'only confirmed orders ship'
      using errcode = '22023', hint = 'order_not_shippable';
  end if;

  v_status := coalesce(
    p_status,
    case v_shipment.delivery_method
      when 'pickup' then 'picked_up'::public.shipment_status
      when 'digital' then 'delivered'::public.shipment_status
      when 'none' then 'delivered'::public.shipment_status
      else 'in_transit'::public.shipment_status
    end
  );

  if v_status not in ('in_transit', 'picked_up', 'delivered') then
    raise exception 'a shipped shipment is in transit, picked up, or delivered'
      using errcode = '22023', hint = 'invalid_status';
  end if;

  for v_line in
    select shipment_lines.id, shipment_lines.order_line_id, shipment_lines.product_id,
      shipment_lines.variant_id, shipment_lines.quantity, shipment_lines.lot_number,
      shipment_lines.serial_number, products.track_inventory, products.product_type,
      order_lines.quantity - order_lines.quantity_cancelled - progress.fulfilled as open_quantity
    from public.shipment_lines
    join public.order_lines on order_lines.id = shipment_lines.order_line_id
    join public.products on products.id = shipment_lines.product_id
    join public.order_line_progress(p_organization_id, v_shipment.order_id) as progress
      on progress.order_line_id = order_lines.id
    where shipment_lines.shipment_id = p_shipment_id
    order by shipment_lines.position, shipment_lines.id
  loop
    if v_line.quantity > v_line.open_quantity then
      raise exception 'shipment quantity exceeds the open quantity'
        using errcode = '22023', hint = 'shipment_over_quantity';
    end if;

    continue when not (v_line.track_inventory and v_line.product_type = 'physical');

    perform public.lock_product_stock(p_organization_id, v_line.product_id);
    v_remaining := v_line.quantity;

    for v_allocation in
      select inventory_allocations.id, inventory_allocations.quantity,
        inventory_stock_records.id as stock_record_id, inventory_stock_records.location_id
      from public.inventory_allocations
      join public.inventory_stock_records
        on inventory_stock_records.id = inventory_allocations.stock_record_id
      where inventory_allocations.order_line_id = v_line.order_line_id
        and inventory_allocations.state = 'reserved'
        and (v_line.lot_number is null or inventory_stock_records.lot_number = v_line.lot_number)
        and (v_line.serial_number is null or inventory_stock_records.serial_number = v_line.serial_number)
      order by
        (inventory_stock_records.location_id is not distinct from v_shipment.location_id) desc,
        inventory_stock_records.expires_on asc nulls last,
        inventory_stock_records.id
    loop
      exit when v_remaining <= 0;
      v_take := least(v_allocation.quantity, v_remaining);

      update public.inventory_stock_records
      set on_hand_quantity = on_hand_quantity - v_take,
        allocated_quantity = allocated_quantity - v_take
      where inventory_stock_records.id = v_allocation.stock_record_id
      returning on_hand_quantity, allocated_quantity
      into v_on_hand, v_reserved;

      if v_take = v_allocation.quantity then
        perform set_config('app.skip_allocation_release', 'on', true);
        delete from public.inventory_allocations
        where inventory_allocations.id = v_allocation.id;
        perform set_config('app.skip_allocation_release', 'off', true);
      else
        update public.inventory_allocations
        set quantity = quantity - v_take
        where inventory_allocations.id = v_allocation.id;
      end if;

      insert into public.inventory_movements (
        organization_id, stock_record_id, product_id, location_id, movement_type,
        on_hand_delta, allocated_delta, quantity_after, allocated_after, reason, created_by,
        order_id, shipment_id, reference_number
      ) values (
        p_organization_id, v_allocation.stock_record_id, v_line.product_id,
        v_allocation.location_id, 'sale', -v_take, -v_take, v_on_hand, v_reserved,
        'order shipped', auth.uid(), v_shipment.order_id, p_shipment_id,
        v_shipment.order_reference
      );

      v_remaining := v_remaining - v_take;
    end loop;

    for v_stock in
      select inventory_stock_records.id, inventory_stock_records.location_id,
        inventory_stock_records.on_hand_quantity - inventory_stock_records.allocated_quantity
          as free_quantity
      from public.inventory_stock_records
      where inventory_stock_records.organization_id = p_organization_id
        and inventory_stock_records.variant_id = v_line.variant_id
        and inventory_stock_records.status = 'available'
        and (
          inventory_stock_records.expires_on is null
          or inventory_stock_records.expires_on >= current_date
        )
        and inventory_stock_records.on_hand_quantity > inventory_stock_records.allocated_quantity
        and (v_line.lot_number is null or inventory_stock_records.lot_number = v_line.lot_number)
        and (v_line.serial_number is null or inventory_stock_records.serial_number = v_line.serial_number)
      order by
        (inventory_stock_records.location_id is not distinct from v_shipment.location_id) desc,
        inventory_stock_records.expires_on asc nulls last,
        inventory_stock_records.id
    loop
      exit when v_remaining <= 0;
      v_take := least(v_stock.free_quantity, v_remaining);

      update public.inventory_stock_records
      set on_hand_quantity = on_hand_quantity - v_take
      where inventory_stock_records.id = v_stock.id
      returning on_hand_quantity, allocated_quantity
      into v_on_hand, v_reserved;

      insert into public.inventory_movements (
        organization_id, stock_record_id, product_id, location_id, movement_type,
        on_hand_delta, allocated_delta, quantity_after, allocated_after, reason, created_by,
        order_id, shipment_id, reference_number
      ) values (
        p_organization_id, v_stock.id, v_line.product_id, v_stock.location_id, 'sale',
        -v_take, 0, v_on_hand, v_reserved, 'order shipped', auth.uid(),
        v_shipment.order_id, p_shipment_id, v_shipment.order_reference
      );

      v_remaining := v_remaining - v_take;
    end loop;

    if v_remaining > 0 then
      raise exception 'not enough stock to ship this shipment'
        using errcode = '23514', hint = 'shipment_insufficient_stock';
    end if;
  end loop;

  perform set_config('app.shipment_transition', 'on', true);
  update public.shipments
  set status = v_status,
    shipped_at = now(),
    delivered_at = case when v_status in ('picked_up', 'delivered') then now() end,
    status_occurred_at = now()
  where shipments.id = p_shipment_id;
  perform set_config('app.shipment_transition', 'off', true);

  perform public.allocate_order_lines(p_organization_id, v_shipment.order_id);

  return jsonb_build_object(
    'status', v_status,
    'orderId', v_shipment.order_id,
    'orderStatus', public.refresh_order_status(p_organization_id, v_shipment.order_id)
  );
end;

