declare
  v_employee_id uuid;
  v_auto boolean;
  v_first_name text;
  v_last_name text;
  v_email text;
  v_timezone text;
  v_username text;
begin
  select id into v_employee_id
  from public.employees
  where organization_id = p_organization_id and user_id = p_user_id;

  if v_employee_id is not null then
    update public.employees
    set
      status = case when status = 'ended' then 'active'::public.employee_status else status end,
      end_date = case when status = 'ended' then null else end_date end
    where id = v_employee_id
      and status = 'ended'
      and archived_at is null;
    return v_employee_id;
  end if;

  select coalesce(auto_create_employee_for_members, true) into v_auto
  from public.hr_settings
  where organization_id = p_organization_id;

  if v_auto is false then
    return null;
  end if;

  select first_name, last_name, email, timezone, username
  into v_first_name, v_last_name, v_email, v_timezone, v_username
  from public.profiles
  where user_id = p_user_id;

  insert into public.employees (
    organization_id, user_id, kind, status, first_name, last_name, work_email,
    timezone, start_date
  )
  values (
    p_organization_id,
    p_user_id,
    'employee',
    'active',
    coalesce(nullif(trim(v_first_name), ''), nullif(split_part(coalesce(v_email, ''), '@', 1), ''), v_username, 'Member'),
    nullif(trim(v_last_name), ''),
    v_email,
    v_timezone,
    (now() at time zone 'utc')::date
  )
  on conflict (organization_id, user_id) where user_id is not null do nothing
  returning id into v_employee_id;

  return v_employee_id;
end;

