begin
  select order_lines.id, order_lines.product_id, order_lines.variant_id,
    coalesce(product_variants.allow_backorder, false) as allow_backorder
  into v_line
  from public.order_lines
  left join public.product_variants on product_variants.id = order_lines.variant_id
  where order_lines.id = p_order_line_id
    and order_lines.organization_id = p_organization_id;

  if coalesce(p_shortfall, 0) > 0 and v_line.allow_backorder then
    insert into public.inventory_allocations (
      organization_id, stock_record_id, product_id, variant_id, quantity, state, order_line_id
    ) values (
      p_organization_id, null, v_line.product_id, v_line.variant_id, p_shortfall,
      'backordered', v_line.id
    )
    on conflict (order_line_id) where order_line_id is not null and state = 'backordered'
    do update set quantity = excluded.quantity;
    return true;
  end if;

  delete from public.inventory_allocations
  where inventory_allocations.order_line_id = p_order_line_id
    and inventory_allocations.state = 'backordered';
  return false;
end;

