declare
  v_organization_id uuid;
  v_customer_id bigint;
  v_promotions uuid[];
begin
  if p_subject_type = 'quote' then
    select quotes.organization_id, quotes.customer_id,
      array_remove(array_append(array(
        select distinct quote_lines.promotion_id from public.quote_lines
        where quote_lines.quote_id = quotes.id and quote_lines.promotion_id is not null
      ), quotes.promotion_id), null)
    into v_organization_id, v_customer_id, v_promotions
    from public.quotes where quotes.id = p_subject_id;
  elsif p_subject_type = 'order' then
    select orders.organization_id, orders.customer_id,
      array_remove(array_append(array(
        select distinct order_lines.promotion_id from public.order_lines
        where order_lines.order_id = orders.id and order_lines.promotion_id is not null
      ), orders.promotion_id), null)
    into v_organization_id, v_customer_id, v_promotions
    from public.orders where orders.id = p_subject_id;
  else
    select invoices.organization_id, invoices.customer_id,
      case when invoices.order_id is not null or invoices.kind = 'credit_note' then '{}'::uuid[]
      else array_remove(array_append(array(
        select distinct invoice_lines.promotion_id from public.invoice_lines
        where invoice_lines.invoice_id = invoices.id and invoice_lines.promotion_id is not null
      ), invoices.promotion_id), null) end
    into v_organization_id, v_customer_id, v_promotions
    from public.invoices where invoices.id = p_subject_id;
  end if;

  if v_organization_id is null then
    return;
  end if;

  delete from public.promotion_redemptions
  where promotion_redemptions.subject_type = p_subject_type
    and promotion_redemptions.subject_id = p_subject_id
    and promotion_redemptions.state = 'pending'
    and not (promotion_redemptions.promotion_id = any (v_promotions));

  insert into public.promotion_redemptions (
    organization_id, promotion_id, customer_id, subject_type, subject_id
  )
  select v_organization_id, promotion_id, v_customer_id, p_subject_type, p_subject_id
  from unnest(v_promotions) as promotion_id
  on conflict (promotion_id, subject_type, subject_id) do nothing;
end;

