declare
  v_material record;
  v_allow boolean;
begin
  select task_materials.id, task_materials.task_id, task_materials.product_id,
    task_materials.variant_id, task_materials.stock_state
  into v_material
  from public.task_materials
  where task_materials.id = p_task_material_id
    and task_materials.organization_id = p_organization_id;

  if not found then
    return;
  end if;

  select product_variants.allow_backorder and products.track_inventory
    and products.product_type = 'physical'
  into v_allow
  from public.product_variants
  join public.products on products.id = product_variants.product_id
  where product_variants.id = v_material.variant_id;

  if coalesce(p_shortfall, 0) > 0 and coalesce(v_allow, false)
    and v_material.stock_state <> 'consumed'
  then
    insert into public.inventory_allocations (
      organization_id, stock_record_id, product_id, variant_id, quantity, state, task_material_id
    ) values (
      p_organization_id, null, v_material.product_id, v_material.variant_id, p_shortfall,
      'backordered', v_material.id
    )
    on conflict (task_material_id) where task_material_id is not null and state = 'backordered'
    do update set quantity = excluded.quantity;
  else
    delete from public.inventory_allocations
    where inventory_allocations.task_material_id = v_material.id
      and inventory_allocations.state = 'backordered';
  end if;

  perform public.apply_task_parts_hold(p_organization_id, v_material.task_id);
end;

