declare
  v_on date := coalesce(p_on, (now() at time zone 'utc')::date);
  v_total numeric;
begin
  select coalesce(sum(hours), 0) into v_total
  from public.time_off_ledger
  where employee_id = p_employee_id
    and time_off_type_id = p_time_off_type_id
    and (kind = 'taken' or effective_on <= v_on);

  return round(v_total, 2);
end;

declare
  v_type public.time_off_types;
  v_default boolean;
begin
  select * into v_type from public.time_off_types where id = p_time_off_type_id;

  if v_type.id is null then
    return true;
  end if;

  if v_type.category = 'sick' then
    return false;
  end if;

  if v_type.requires_approval is not null then
    return v_type.requires_approval;
  end if;

  select time_off_requires_approval into v_default
  from public.hr_settings
  where organization_id = v_type.organization_id;

  return coalesce(v_default, true);
end;

