functions.definition:
declare
  v_remaining numeric(12, 3);
  v_moved numeric(12, 3) := 0;
  v_take numeric(12, 3);
  v_source record;
  v_dest_id uuid;
  v_on_hand numeric(12, 3);
  v_reserved numeric(12, 3);
  v_quote_id uuid;
  v_invoice_id uuid;
  v_task_material_id uuid;
begin
  if p_quantity is null or p_quantity <= 0 then
    return 0;
  end if;

  perform public.lock_product_stock(p_organization_id, p_product_id);
  v_remaining := p_quantity;
  v_task_material_id := coalesce(p_to_task_material_id, p_from_task_material_id);

  if p_from_quote_version_line_id is not null or p_to_quote_version_line_id is not null then
    select quote_versions.quote_id
    into v_quote_id
    from public.quote_version_lines
    join public.quote_versions
      on quote_versions.id = quote_version_lines.quote_version_id
    where quote_version_lines.id = coalesce(p_from_quote_version_line_id, p_to_quote_version_line_id);
  end if;

  if p_from_invoice_line_id is not null or p_to_invoice_line_id is not null then
    select invoice_lines.invoice_id
    into v_invoice_id
    from public.invoice_lines
    where invoice_lines.id = coalesce(p_to_invoice_line_id, p_from_invoice_line_id);
  end if;

  for v_source in
    select
      inventory_allocations.id,
      inventory_allocations.quantity,
      inventory_stock_records.id as stock_record_id,
      inventory_stock_records.location_id,
      inventory_stock_records.on_hand_quantity,
      inventory_stock_records.allocated_quantity
    from public.inventory_allocations
    join public.inventory_stock_records
      on inventory_stock_records.id = inventory_allocations.stock_record_id
    where inventory_allocations.organization_id = p_organization_id
      and inventory_allocations.product_id = p_product_id
      and inventory_allocations.state = 'reserved'
      and inventory_allocations.task_material_id is not distinct from p_from_task_material_id
      and inventory_allocations.quote_version_line_id is not distinct from p_from_quote_version_line_id
      and inventory_allocations.invoice_line_id is not distinct from p_from_invoice_line_id
    order by
      inventory_stock_records.expires_on asc nulls last,
      inventory_stock_records.id
  loop
    exit when v_remaining <= 0;
    v_take := least(v_source.quantity, v_remaining);

    select inventory_allocations.id
    into v_dest_id
    from public.inventory_allocations
    where inventory_allocations.organization_id = p_organization_id
      and inventory_allocations.stock_record_id = v_source.stock_record_id
      and inventory_allocations.state = 'reserved'
      and inventory_allocations.task_material_id is not distinct from p_to_task_material_id
      and inventory_allocations.quote_version_line_id is not distinct from p_to_quote_version_line_id
      and inventory_allocations.invoice_line_id is not distinct from p_to_invoice_line_id
      and inventory_allocations.id <> v_source.id;

    if v_dest_id is not null then
      update public.inventory_allocations
      set quantity = quantity + v_take
      where inventory_allocations.id = v_dest_id;

      if v_take = v_source.quantity then
        perform set_config('app.skip_allocation_release', 'on', true);
        delete from public.inventory_allocations where inventory_allocations.id = v_source.id;
        perform set_config('app.skip_allocation_release', 'off', true);
      else
        update public.inventory_allocations
        set quantity = quantity - v_take
        where inventory_allocations.id = v_source.id;
      end if;
    elsif v_take = v_source.quantity then
      update public.inventory_allocations
      set
        task_material_id = p_to_task_material_id,
        quote_version_line_id = p_to_quote_version_line_id,
        invoice_line_id = p_to_invoice_line_id
      where inventory_allocations.id = v_source.id;
    else
      update public.inventory_allocations
      set quantity = quantity - v_take
      where inventory_allocations.id = v_source.id;

      perform public.upsert_reserved_allocation(
        p_organization_id,
        v_source.stock_record_id,
        p_product_id,
        v_take,
        p_to_task_material_id,
        p_to_quote_version_line_id,
        p_to_invoice_line_id
      );
    end if;

    perform public.write_inventory_movement(
      p_organization_id,
      v_source.stock_record_id,
      p_product_id,
      v_source.location_id,
      'reservation_transfer',
      0,
      0,
      v_source.on_hand_quantity,
      v_source.allocated_quantity,
      coalesce(p_reason, 'reservation transferred'),
      p_created_by,
      v_task_material_id,
      v_quote_id,
      v_invoice_id
    );

    v_remaining := v_remaining - v_take;
    v_moved := v_moved + v_take;
  end loop;

  return v_moved;
end;

functions.complete_statement:
CREATE OR REPLACE FUNCTION public.transfer_allocations(p_organization_id uuid, p_product_id uuid, p_quantity numeric, p_from_task_material_id uuid, p_from_quote_version_line_id uuid, p_from_invoice_line_id uuid, p_to_task_material_id uuid, p_to_quote_version_line_id uuid, p_to_invoice_line_id uuid, p_reason text, p_created_by uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_remaining numeric(12, 3);
  v_moved numeric(12, 3) := 0;
  v_take numeric(12, 3);
  v_source record;
  v_dest_id uuid;
  v_on_hand numeric(12, 3);
  v_reserved numeric(12, 3);
  v_quote_id uuid;
  v_invoice_id uuid;
  v_task_material_id uuid;
begin
  if p_quantity is null or p_quantity <= 0 then
    return 0;
  end if;

  perform public.lock_product_stock(p_organization_id, p_product_id);
  v_remaining := p_quantity;
  v_task_material_id := coalesce(p_to_task_material_id, p_from_task_material_id);

  if p_from_quote_version_line_id is not null or p_to_quote_version_line_id is not null then
    select quote_versions.quote_id
    into v_quote_id
    from public.quote_version_lines
    join public.quote_versions
      on quote_versions.id = quote_version_lines.quote_version_id
    where quote_version_lines.id = coalesce(p_from_quote_version_line_id, p_to_quote_version_line_id);
  end if;

  if p_from_invoice_line_id is not null or p_to_invoice_line_id is not null then
    select invoice_lines.invoice_id
    into v_invoice_id
    from public.invoice_lines
    where invoice_lines.id = coalesce(p_to_invoice_line_id, p_from_invoice_line_id);
  end if;

  for v_source in
    select
      inventory_allocations.id,
      inventory_allocations.quantity,
      inventory_stock_records.id as stock_record_id,
      inventory_stock_records.location_id,
      inventory_stock_records.on_hand_quantity,
      inventory_stock_records.allocated_quantity
    from public.inventory_allocations
    join public.inventory_stock_records
      on inventory_stock_records.id = inventory_allocations.stock_record_id
    where inventory_allocations.organization_id = p_organization_id
      and inventory_allocations.product_id = p_product_id
      and inventory_allocations.state = 'reserved'
      and inventory_allocations.task_material_id is not distinct from p_from_task_material_id
      and inventory_allocations.quote_version_line_id is not distinct from p_from_quote_version_line_id
      and inventory_allocations.invoice_line_id is not distinct from p_from_invoice_line_id
    order by
      inventory_stock_records.expires_on asc nulls last,
      inventory_stock_records.id
  loop
    exit when v_remaining <= 0;
    v_take := least(v_source.quantity, v_remaining);

    select inventory_allocations.id
    into v_dest_id
    from public.inventory_allocations
    where inventory_allocations.organization_id = p_organization_id
      and inventory_allocations.stock_record_id = v_source.stock_record_id
      and inventory_allocations.state = 'reserved'
      and inventory_allocations.task_material_id is not distinct from p_to_task_material_id
      and inventory_allocations.quote_version_line_id is not distinct from p_to_quote_version_line_id
      and inventory_allocations.invoice_line_id is not distinct from p_to_invoice_line_id
      and inventory_allocations.id <> v_source.id;

    if v_dest_id is not null then
      update public.inventory_allocations
      set quantity = quantity + v_take
      where inventory_allocations.id = v_dest_id;

      if v_take = v_source.quantity then
        perform set_config('app.skip_allocation_release', 'on', true);
        delete from public.inventory_allocations where inventory_allocations.id = v_source.id;
        perform set_config('app.skip_allocation_release', 'off', true);
      else
        update public.inventory_allocations
        set quantity = quantity - v_take
        where inventory_allocations.id = v_source.id;
      end if;
    elsif v_take = v_source.quantity then
      update public.inventory_allocations
      set
        task_material_id = p_to_task_material_id,
        quote_version_line_id = p_to_quote_version_line_id,
        invoice_line_id = p_to_invoice_line_id
      where inventory_allocations.id = v_source.id;
    else
      update public.inventory_allocations
      set quantity = quantity - v_take
      where inventory_allocations.id = v_source.id;

      perform public.upsert_reserved_allocation(
        p_organization_id,
        v_source.stock_record_id,
        p_product_id,
        v_take,
        p_to_task_material_id,
        p_to_quote_version_line_id,
        p_to_invoice_line_id
      );
    end if;

    perform public.write_inventory_movement(
      p_organization_id,
      v_source.stock_record_id,
      p_product_id,
      v_source.location_id,
      'reservation_transfer',
      0,
      0,
      v_source.on_hand_quantity,
      v_source.allocated_quantity,
      coalesce(p_reason, 'reservation transferred'),
      p_created_by,
      v_task_material_id,
      v_quote_id,
      v_invoice_id
    );

    v_remaining := v_remaining - v_take;
    v_moved := v_moved + v_take;
  end loop;

  return v_moved;
end;
$function$

