declare
  v_node public.file_nodes;
  v_batch_id uuid := gen_random_uuid();
  v_now timestamptz := now() at time zone 'utc';
  v_purge_after timestamptz;
begin
  select *
  into v_node
  from public.file_nodes
  where customer_id = p_customer_id
    and parent_id is null
    and deleted_at is null
  for update;

  if v_node.id is null then
    return null;
  end if;

  v_purge_after := v_now + make_interval(
    days => public.get_file_retention_days(v_node.organization_id)
  );

  with recursive subtree as (
    select id from public.file_nodes where id = v_node.id
    union
    select child.id
    from public.file_nodes as child
    inner join subtree as parent on child.parent_id = parent.id
    where child.deleted_at is null
  )
  update public.file_nodes
  set
    deleted_at = v_now,
    deletion_batch_id = v_batch_id,
    deleted_by = (select auth.uid()),
    purge_after = v_purge_after
  where id in (select id from subtree);
  return v_batch_id;
end;

