  v_purge_after timestamptz;
begin
  select * into v_node from public.file_nodes where id = p_node_id for update;
  if v_node.id is null or v_node.deleted_at is not null then
    raise exception 'File node not found' using errcode = 'P0002';
  end if;
  if not public.has_file_node_access(v_node.id, 'editor')
    or not public.has_org_permission(v_node.organization_id, 'organization.files.delete') then
    raise exception 'File node deletion is not allowed' using errcode = '42501';
  end if;
  if v_node.customer_id is not null and v_node.parent_id is null then
    raise exception 'Customer folders cannot be deleted from Files' using errcode = '42501';
  end if;
  v_purge_after := v_now + make_interval(days => public.get_file_retention_days(v_node.organization_id));

  with recursive subtree as (
    select id from public.file_nodes where id = v_node.id
    union
    select child.id
    from public.file_nodes as child
    inner join subtree as parent on child.parent_id = parent.id
    where child.deleted_at is null
  )
  update public.file_nodes
  set
    deleted_at = v_now,
    deletion_batch_id = v_batch_id,
    deleted_by = (select auth.uid()),
    purge_after = v_purge_after
  where id in (select id from subtree);
  return v_batch_id;
end;

