declare
  v_shipment record;
  v_occurred timestamptz := coalesce(p_occurred_at, now());
  v_allowed boolean;
begin
  select shipments.id, shipments.direction, shipments.status, shipments.delivery_method,
    shipments.shipped_at, shipments.delivered_at, shipments.status_occurred_at
  into v_shipment
  from public.shipments
  where shipments.id = p_shipment_id
    and shipments.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'shipment not found' using errcode = 'P0002';
  end if;

  if not public.has_org_permission(
    p_organization_id,
    case when v_shipment.direction = 'inbound'
      then 'organization.purchase-orders.receive'
      else 'organization.orders.fulfill'
    end
  ) then
    raise insufficient_privilege using message = 'shipment permission required';
  end if;

  if v_shipment.status_occurred_at is not null and v_occurred < v_shipment.status_occurred_at then
    return v_shipment.status;
  end if;

  v_allowed := case
    when v_shipment.status = 'cancelled' or v_shipment.delivered_at is not null then false
    when v_shipment.direction = 'outbound' and v_shipment.shipped_at is null then
      p_status in ('draft', 'packed')
      or (p_status = 'ready_for_pickup' and v_shipment.delivery_method = 'pickup')
    when v_shipment.direction = 'outbound' then p_status in ('in_transit', 'delivered', 'exception')
    else p_status in ('draft', 'packed', 'in_transit', 'exception')
  end;

  if not v_allowed then
    raise exception 'this shipment cannot move to that status'
      using errcode = '22023', hint = 'invalid_status';
  end if;

  perform set_config('app.shipment_transition', 'on', true);
  update public.shipments
  set status = p_status,
    delivered_at = case when p_status = 'delivered' then v_occurred else delivered_at end,
    status_occurred_at = v_occurred
  where shipments.id = p_shipment_id;
  perform set_config('app.shipment_transition', 'off', true);

  return p_status;
end;

