CREATE OR REPLACE FUNCTION public.upsert_task_material(p_organization_id uuid, p_task_id uuid, p_material jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_task_status public.task_status;
  v_material public.task_materials%rowtype;
  v_product public.products%rowtype;
  v_material_id uuid;
  v_requested_quantity numeric(12, 3);
  v_tracked_count integer;
  v_requested_state public.task_material_stock_state;
begin
  if v_user_id is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;

  if not public.has_org_permission(
    p_organization_id,
    'organization.tasks.update'
  ) then
    raise insufficient_privilege using message = 'task update permission required';
  end if;

  if p_material is null or jsonb_typeof(p_material) <> 'object' then
    raise exception 'task material must be an object' using errcode = '22023';
  end if;

  select tasks.status
  into v_task_status
  from public.tasks
  where tasks.id = p_task_id
    and tasks.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'task not found in organization' using errcode = '23503';
  end if;

  if v_task_status = 'done' then
    raise exception 'materials cannot be added or updated while the task is done'
      using errcode = '23514';
  end if;

  if p_material ? 'id' and nullif(p_material ->> 'id', '') is not null then
    v_material_id := (p_material ->> 'id')::uuid;

    select task_materials.*
    into v_material
    from public.task_materials
    where task_materials.id = v_material_id
      and task_materials.organization_id = p_organization_id
      and task_materials.task_id = p_task_id
    for update;

    if not found then
      raise exception 'task material not found in organization task'
        using errcode = '23503';
    end if;

    if v_material.stock_state = 'consumed'
      and (
        not p_material ? 'stock_state'
        or nullif(p_material ->> 'stock_state', '') is null
        or (p_material ->> 'stock_state') = 'consumed'
      )
    then
      raise exception 'consumed task materials cannot be updated until the task is reopened'
        using errcode = '23514';
    end if;

    if p_material ? 'product_id'
      and (p_material ->> 'product_id')::uuid is distinct from v_material.product_id
    then
      raise exception 'task material product cannot be changed'
        using errcode = '23514';
    end if;
  else
    if nullif(p_material ->> 'product_id', '') is null then
      raise exception 'task material product_id is required' using errcode = '22023';
    end if;

    select task_materials.*
    into v_material
    from public.task_materials
    where task_materials.organization_id = p_organization_id
      and task_materials.task_id = p_task_id
      and task_materials.variant_id = coalesce(
        nullif(p_material ->> 'variant_id', '')::uuid,
        public.product_default_variant_id((p_material ->> 'product_id')::uuid)
      )
    for update;

    if found then
      v_material_id := v_material.id;

      if v_material.stock_state = 'consumed'
        and (
          not p_material ? 'stock_state'
          or nullif(p_material ->> 'stock_state', '') is null
          or (p_material ->> 'stock_state') = 'consumed'
        )
      then
        raise exception 'consumed task materials cannot be updated until the task is reopened'
          using errcode = '23514';
      end if;
    else
      v_material_id := gen_random_uuid();
    end if;
  end if;

  select products.*
  into v_product
  from public.products
  where products.id = coalesce(
      v_material.product_id,
      (p_material ->> 'product_id')::uuid
    )
    and products.organization_id = p_organization_id;

  if not found then
    raise exception 'task material product not found in organization'
      using errcode = '23503';
  end if;

  v_requested_quantity := case
    when p_material ? 'quantity' then (p_material ->> 'quantity')::numeric
    else v_material.quantity
  end;

  if v_requested_quantity is null or v_requested_quantity <= 0 then
    raise exception 'task material quantity must be greater than zero'
      using errcode = '23514';
  end if;

  if p_material ? 'stock_state' and nullif(p_material ->> 'stock_state', '') is not null then
    v_requested_state := (p_material ->> 'stock_state')::public.task_material_stock_state;
  end if;

  if v_material.id is null then
    insert into public.task_materials (
      id,
      organization_id,
      task_id,
      product_id,
      quantity,
      unit,
      unit_price,
      vat_rate,
      currency,
      stock_state,
      notes,
      position,
      created_by,
      updated_by,
      billable,
      variant_id
    ) values (
      v_material_id,
      p_organization_id,
      p_task_id,
      v_product.id,
      v_requested_quantity,
      case
        when p_material ? 'unit' then p_material ->> 'unit'
        else v_product.unit_of_measure
      end,
      case
        when p_material ? 'unit_price' then (p_material ->> 'unit_price')::numeric
        else coalesce(
          (select product_variants.selling_price from public.product_variants
            where product_variants.id = nullif(p_material ->> 'variant_id', '')::uuid
              and product_variants.product_id = v_product.id),
          v_product.default_selling_price,
          0
        )
      end,
      case
        when p_material ? 'vat_rate' then (p_material ->> 'vat_rate')::numeric
        else coalesce(v_product.vat_percentage, 0)
      end,
      case
        when p_material ? 'currency' then p_material ->> 'currency'
        else coalesce(v_product.currency, 'EUR')
      end,
      'untracked',
      case when p_material ? 'notes' then p_material ->> 'notes' else null end,
      case
        when p_material ? 'position' then (p_material ->> 'position')::numeric
        else 0
      end,
      v_user_id,
      v_user_id,
      case
        when p_material ? 'billable' then (p_material ->> 'billable')::boolean
        else true
      end,
      nullif(p_material ->> 'variant_id', '')::uuid
    )
    returning * into v_material;
  else
    update public.task_materials
    set
      quantity = v_requested_quantity,
      unit = case
        when p_material ? 'unit' then p_material ->> 'unit'
        else task_materials.unit
      end,
      unit_price = case
        when p_material ? 'unit_price' then (p_material ->> 'unit_price')::numeric
        else task_materials.unit_price
      end,
      vat_rate = case
        when p_material ? 'vat_rate' then (p_material ->> 'vat_rate')::numeric
        else task_materials.vat_rate
      end,
      currency = case
        when p_material ? 'currency' then p_material ->> 'currency'
        else task_materials.currency
      end,
      notes = case
        when p_material ? 'notes' then p_material ->> 'notes'
        else task_materials.notes
      end,
      position = case
        when p_material ? 'position' then (p_material ->> 'position')::numeric
        else task_materials.position
      end,
      billable = case
        when p_material ? 'billable' then (p_material ->> 'billable')::boolean
        else task_materials.billable
      end,
      updated_by = v_user_id
    where task_materials.id = v_material_id
    returning * into v_material;
  end if;

  select count(*)
  into v_tracked_count
  from public.inventory_stock_records
  where inventory_stock_records.organization_id = p_organization_id
    and inventory_stock_records.product_id = v_material.product_id;

  if v_tracked_count = 0 and exists (
    select 1
    from public.product_variants
    join public.products on products.id = product_variants.product_id
    where product_variants.id = v_material.variant_id
      and product_variants.allow_backorder
      and products.track_inventory
      and products.product_type = 'physical'
  ) then
    v_tracked_count := 1;
  end if;

  if v_material.stock_state = 'consumed' then
    perform public.restore_allocations(
      p_organization_id,
      v_material_id,
      null,
      null,
      'task material restored after status change',
      v_material.quote_id,
      null,
      v_user_id
    );
  end if;

  if v_tracked_count = 0 then
    update public.task_materials
    set
      stock_state = case
        when v_requested_state = 'consumed' then 'consumed'::public.task_material_stock_state
        else 'untracked'::public.task_material_stock_state
      end,
      consumed_at = case
        when v_requested_state = 'consumed' then now()
        else null
      end,
      updated_by = v_user_id
    where task_materials.id = v_material_id;

    return v_material_id;
  end if;

  perform public.reconcile_owner_allocations(
    p_organization_id,
    v_material.product_id,
    v_requested_quantity,
    v_material_id,
    null,
    null,
    'task material reserved',
    v_material.quote_id,
    null,
    v_user_id
  );

  if v_requested_state = 'consumed' then
    perform public.consume_allocations(
      p_organization_id,
      v_material_id,
      null,
      null,
      'task material consumed',
      v_material.quote_id,
      null,
      v_user_id
    );

    update public.task_materials
    set
      stock_state = 'consumed',
      consumed_at = now(),
      updated_by = v_user_id
    where task_materials.id = v_material_id;

    perform public.sync_task_material_backorder(p_organization_id, v_material_id, 0);

    return v_material_id;
  end if;

  update public.task_materials
  set
    stock_state = 'reserved',
    consumed_at = null,
    updated_by = v_user_id
  where task_materials.id = v_material_id;

  return v_material_id;
end;
